// Benchmark: induction_safe.c
// Expected: TRUE (provable by k-induction)
// Loop invariant: x is always even (x % 2 == 0)
extern unsigned __VERIFIER_nondet_uint();
extern void __assert_fail(const char *assertion, const char *file,
                          unsigned int line, const char *function);
int main() {
  int x = 0;
  int n = __VERIFIER_nondet_uint();
  while (x < n) {
    x = x + 2;
  }
  if (x % 2 != 0) {
    __assert_fail("x_is_even", "induction_safe.c", 13, "main");
  }
  return 0;
}
