// Benchmark: induction_unsafe.c
// Expected: FALSE (k-induction finds counterexample)
// The increment by 3 means x can be odd
extern unsigned __VERIFIER_nondet_uint();
extern void __assert_fail(const char *assertion, const char *file,
                          unsigned int line, const char *function);
int main() {
  int x = 0;
  int n = __VERIFIER_nondet_uint();
  while (x < n) {
    x = x + 3;
  }
  if (x % 2 != 0) {
    __assert_fail("x_is_even", "induction_unsafe.c", 13, "main");
  }
  return 0;
}
