"""CPA Interface Definitions.

A Configurable Program Analysis (CPA) is defined by:
- An abstract domain D (lattice of abstract states)
- A transfer relation (computes successors)
- A merge operator (combines states at same location)
- A stop operator (checks if a state is covered)
- A precision (controls analysis granularity)
"""

from abc import ABC, abstractmethod
from typing import Any


class AbstractState(ABC):
    """Base class for abstract states in a CPA."""

    @abstractmethod
    def __eq__(self, other) -> bool:
        pass

    @abstractmethod
    def __hash__(self) -> int:
        pass

    @abstractmethod
    def __repr__(self) -> str:
        pass


class Precision(ABC):
    """Controls the granularity of the analysis."""
    pass


class AbstractDomain(ABC):
    """Defines the lattice operations for abstract states."""

    @abstractmethod
    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        """Check if state1 is subsumed by state2 (state1 ⊑ state2)."""
        pass

    @abstractmethod
    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        """Compute least upper bound of two states."""
        pass

    @abstractmethod
    def get_top(self) -> AbstractState:
        """Return the top element (represents all states)."""
        pass

    @abstractmethod
    def get_bottom(self) -> AbstractState:
        """Return the bottom element (represents no states)."""
        pass


class TransferRelation(ABC):
    """Computes successor abstract states."""

    @abstractmethod
    def get_abstract_successors(
        self, state: AbstractState, precision: Precision, edge: Any
    ) -> list[AbstractState]:
        """Compute abstract successors for a given CFA edge."""
        pass


class MergeOperator(ABC):
    """Determines how to combine abstract states at the same location."""

    @abstractmethod
    def merge(
        self, state1: AbstractState, state2: AbstractState, precision: Precision
    ) -> AbstractState:
        """Merge state1 into state2. Return state2 unchanged for 'sep' semantics."""
        pass


class StopOperator(ABC):
    """Determines if a state is already covered by the reached set."""

    @abstractmethod
    def stop(
        self, state: AbstractState, reached: set, precision: Precision
    ) -> bool:
        """Check if state is covered by some state in reached."""
        pass


class ConfigurableProgramAnalysis(ABC):
    """Main CPA interface combining all components."""

    @abstractmethod
    def get_abstract_domain(self) -> AbstractDomain:
        pass

    @abstractmethod
    def get_transfer_relation(self) -> TransferRelation:
        pass

    @abstractmethod
    def get_merge_operator(self) -> MergeOperator:
        pass

    @abstractmethod
    def get_stop_operator(self) -> StopOperator:
        pass

    @abstractmethod
    def get_initial_state(self, node_id: int) -> AbstractState:
        pass

    @abstractmethod
    def get_initial_precision(self) -> Precision:
        pass

