"""Explicit-value analysis and the generic CPA worklist algorithm.

This module contains the core of the framework:

* :class:`LocationCPA`     -- tracks the program counter (a CFA node).
* :class:`ExplicitValueCPA`-- tracks concrete integer values of variables.
* :class:`CompositeCPA`    -- component-wise product of several CPAs.
* :class:`CPAAlgorithm`    -- the generic reachability (worklist) algorithm.
* :func:`run_value_analysis` -- entry point used by ``cpachecker_main.py``.

The implementation follows the classic CPA algorithm of Beyer/Henzinger/Theoduloz:

    while waitlist is not empty:
        pop e from waitlist
        for each e' in transfer(e):
            for each e'' in reached:
                e_new = merge(e', e'')
                if e_new != e'':
                    replace e'' by e_new in reached and waitlist
            if not stop(e', reached):
                add e' to reached and waitlist
"""

from __future__ import annotations

import time
from typing import Any, Callable, Iterable, Optional

from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import evaluate_condition, evaluate_expression
from cpachecker.result import Verdict, VerificationResult

# Default resource limits for the reachability engine.  They keep the analysis
# from running forever on programs whose abstract state space does not converge.
DEFAULT_MAX_STATES = 400000


class _TopValue:
    """Singleton lattice element meaning "this variable may hold any value"."""

    _instance: Optional["_TopValue"] = None

    def __new__(cls) -> "_TopValue":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:
        return "TOP"


TOP = _TopValue()


# ---------------------------------------------------------------------------
# Generic helpers shared by every CPA in this framework
# ---------------------------------------------------------------------------


class SingletonPrecision(Precision):
    """Trivial precision: the analysis has a single, fixed granularity."""

    def __repr__(self) -> str:
        return "<prec>"


class SepMergeOperator(MergeOperator):
    """``merge-sep``: never combine two abstract states."""

    def merge(self, state1: AbstractState, state2: AbstractState,
              precision: Precision) -> AbstractState:
        return state2


class JoinMergeOperator(MergeOperator):
    """``merge-join``: replace both states by their least upper bound."""

    def __init__(self, domain: AbstractDomain):
        self.domain = domain

    def merge(self, state1: AbstractState, state2: AbstractState,
              precision: Precision) -> AbstractState:
        return self.domain.join(state1, state2)


class CoverageStopOperator(StopOperator):
    """``stop-sep``: covered if some reached state subsumes the new state."""

    def __init__(self, domain: AbstractDomain):
        self.domain = domain

    def stop(self, state: AbstractState, reached: set,
             precision: Precision) -> bool:
        for other in reached:
            if self.domain.is_less_or_equal(state, other):
                return True
        return False


# ---------------------------------------------------------------------------
# LocationCPA -- tracks the program location
# ---------------------------------------------------------------------------


class LocationState(AbstractState):
    """Abstract state of the LocationCPA: just a CFA node id."""

    __slots__ = ("node_id",)

    def __init__(self, node_id: int):
        self.node_id = node_id

    def __eq__(self, other) -> bool:
        return isinstance(other, LocationState) and other.node_id == self.node_id

    def __hash__(self) -> int:
        return hash(("loc", self.node_id))

    def __repr__(self) -> str:
        return f"N{self.node_id}"


class LocationDomain(AbstractDomain):
    """Flat lattice over CFA nodes (only identical locations are comparable)."""

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        return state1 == state2

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        if state1 == state2:
            return state1
        raise ValueError("LocationCPA has no join for different locations")

    def get_top(self) -> AbstractState:
        return LocationState(-1)

    def get_bottom(self) -> AbstractState:
        return LocationState(-2)


class LocationTransferRelation(TransferRelation):
    """Follows a CFA edge: the successor location is the edge target."""

    def get_abstract_successors(self, state: AbstractState, precision: Precision,
                                edge: CFAEdge) -> list[AbstractState]:
        if edge.source != state.node_id:
            return []
        return [LocationState(edge.target)]


class LocationCPA(ConfigurableProgramAnalysis):
    """CPA that tracks the program counter."""

    def __init__(self, cfa: CFA):
        self.cfa = cfa
        self._domain = LocationDomain()
        self._transfer = LocationTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = CoverageStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return LocationState(node_id)

    def get_initial_precision(self) -> Precision:
        return SingletonPrecision()


# ---------------------------------------------------------------------------
# ExplicitValueCPA -- tracks concrete integer values
# ---------------------------------------------------------------------------


class ValueAnalysisState(AbstractState):
    """Maps variable names to concrete integers.

    A variable that is *absent* from the mapping has the value :data:`TOP`
    (unknown).  Therefore a state with fewer entries is *less precise* and
    subsumes states that assign more variables.
    """

    __slots__ = ("values", "_hash")

    def __init__(self, values: Optional[dict[str, int]] = None):
        self.values: dict[str, int] = dict(values) if values else {}
        self._hash = hash(frozenset(self.values.items()))

    # -- lattice / helper API -------------------------------------------
    def get_value(self, var: str) -> Any:
        return self.values.get(var, TOP)

    def is_top_for(self, var: str) -> bool:
        return var not in self.values

    def assign(self, var: str, value: Any) -> "ValueAnalysisState":
        """Return a copy with ``var`` bound to ``value`` (TOP/None forgets it)."""
        new_values = dict(self.values)
        if value is None or value is TOP:
            new_values.pop(var, None)
        else:
            new_values[var] = int(value)
        return ValueAnalysisState(new_values)

    def is_less_or_equal(self, other: "ValueAnalysisState") -> bool:
        """``self <= other`` iff other is less precise but consistent."""
        for var, val in other.values.items():
            if self.values.get(var) != val:
                return False
        return True

    def join(self, other: "ValueAnalysisState") -> "ValueAnalysisState":
        common = {var: val for var, val in self.values.items()
                  if other.values.get(var) == val}
        return ValueAnalysisState(common)

    def __eq__(self, other) -> bool:
        return isinstance(other, ValueAnalysisState) and other.values == self.values

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        if not self.values:
            return "[]"
        return "[" + ", ".join(f"{k}={v}" for k, v in sorted(self.values.items())) + "]"


class ValueAnalysisDomain(AbstractDomain):
    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        return state1.is_less_or_equal(state2)

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        return state1.join(state2)

    def get_top(self) -> AbstractState:
        return ValueAnalysisState({})

    def get_bottom(self) -> AbstractState:
        # There is no dedicated bottom element; infeasible successors are
        # represented by the empty successor list of the transfer relation.
        return ValueAnalysisState({})


class ValueAnalysisTransferRelation(TransferRelation):
    """Concrete (strongest-postcondition) semantics for explicit values."""

    def get_abstract_successors(self, state: AbstractState, precision: Precision,
                                edge: CFAEdge) -> list[AbstractState]:
        etype = edge.edge_type

        if etype is EdgeType.ASSIGNMENT:
            value = evaluate_expression(edge.expression, state.values)
            return [state.assign(edge.variable, value)]

        if etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            truth = evaluate_condition(edge.expression, state.values)
            if truth is None:
                # Not enough information: both branches stay feasible.
                return [state]
            wanted = etype is EdgeType.ASSUME_TRUE
            return [state] if truth == wanted else []

        # ASSERT / FUNCTION_CALL / BLANK edges do not change the values.
        return [state]


class ExplicitValueCPA(ConfigurableProgramAnalysis):
    """CPA tracking concrete values for all variables of the program."""

    def __init__(self, cfa: CFA):
        self.cfa = cfa
        self._domain = ValueAnalysisDomain()
        self._transfer = ValueAnalysisTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = CoverageStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return ValueAnalysisState({})

    def get_initial_precision(self) -> Precision:
        return SingletonPrecision()


# ---------------------------------------------------------------------------
# CompositeCPA -- component-wise product analysis
# ---------------------------------------------------------------------------


class CompositeState(AbstractState):
    """Tuple of component abstract states."""

    __slots__ = ("components", "_hash")

    def __init__(self, components: Iterable[AbstractState]):
        self.components = tuple(components)
        self._hash = hash(self.components)

    def __iter__(self):
        return iter(self.components)

    def __len__(self) -> int:
        return len(self.components)

    def __getitem__(self, index: int) -> AbstractState:
        return self.components[index]

    def __eq__(self, other) -> bool:
        return isinstance(other, CompositeState) and other.components == self.components

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        return "(" + ", ".join(repr(c) for c in self.components) + ")"


class CompositePrecision(Precision):
    __slots__ = ("components",)

    def __init__(self, components: Iterable[Precision]):
        self.components = tuple(components)

    def __getitem__(self, index: int) -> Precision:
        return self.components[index]

    def __repr__(self) -> str:
        return "(" + ", ".join(repr(c) for c in self.components) + ")"


class CompositeDomain(AbstractDomain):
    def __init__(self, domains: list[AbstractDomain]):
        self.domains = domains

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        return all(
            domain.is_less_or_equal(s1, s2)
            for domain, s1, s2 in zip(self.domains, state1.components, state2.components)
        )

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        return CompositeState(
            domain.join(s1, s2)
            for domain, s1, s2 in zip(self.domains, state1.components, state2.components)
        )

    def get_top(self) -> AbstractState:
        return CompositeState(d.get_top() for d in self.domains)

    def get_bottom(self) -> AbstractState:
        return CompositeState(d.get_bottom() for d in self.domains)


class CompositeTransferRelation(TransferRelation):
    """Applies every component transfer relation to the same CFA edge.

    The successors are the cartesian product of the component successors; if
    any component reports no successor (infeasible edge) the whole composite
    edge is infeasible.
    """

    def __init__(self, transfers: list[TransferRelation]):
        self.transfers = transfers

    def get_abstract_successors(self, state: AbstractState, precision: Precision,
                                edge: CFAEdge) -> list[AbstractState]:
        per_component: list[list[AbstractState]] = []
        for index, transfer in enumerate(self.transfers):
            successors = transfer.get_abstract_successors(
                state[index], precision[index], edge
            )
            if not successors:
                return []
            per_component.append(successors)

        combinations: list[list[AbstractState]] = [[]]
        for successors in per_component:
            combinations = [prefix + [s] for prefix in combinations for s in successors]
        return [CompositeState(c) for c in combinations]


class CompositeMergeOperator(MergeOperator):
    """Component-wise merge; with ``sep`` components nothing is merged."""

    def __init__(self, merges: list[MergeOperator]):
        self.merges = merges

    def merge(self, state1: AbstractState, state2: AbstractState,
              precision: Precision) -> AbstractState:
        merged = [
            merge_op.merge(s1, s2, precision[index])
            for index, (merge_op, s1, s2) in enumerate(
                zip(self.merges, state1.components, state2.components)
            )
        ]
        candidate = CompositeState(merged)
        return candidate


class CompositeStopOperator(StopOperator):
    """A composite state is covered if some reached state subsumes it."""

    def __init__(self, domain: CompositeDomain):
        self.domain = domain

    def stop(self, state: AbstractState, reached: set,
             precision: Precision) -> bool:
        for other in reached:
            if self.domain.is_less_or_equal(state, other):
                return True
        return False


class CompositeCPA(ConfigurableProgramAnalysis):
    """Product CPA, e.g. LocationCPA x ExplicitValueCPA."""

    def __init__(self, cpas: list[ConfigurableProgramAnalysis]):
        if not cpas:
            raise ValueError("CompositeCPA needs at least one component")
        self.cpas = list(cpas)
        self._domain = CompositeDomain([c.get_abstract_domain() for c in self.cpas])
        self._transfer = CompositeTransferRelation(
            [c.get_transfer_relation() for c in self.cpas]
        )
        self._merge = CompositeMergeOperator(
            [c.get_merge_operator() for c in self.cpas]
        )
        self._stop = CompositeStopOperator(self._domain)
        self._location_index = next(
            (i for i, c in enumerate(self.cpas) if isinstance(c, LocationCPA)), None
        )

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return CompositeState(c.get_initial_state(node_id) for c in self.cpas)

    def get_initial_precision(self) -> Precision:
        return CompositePrecision(c.get_initial_precision() for c in self.cpas)

    # -- extra API used by the reachability algorithm --------------------
    def get_location(self, state: AbstractState) -> int:
        """Extract the program location of a composite state."""
        if self._location_index is None:
            raise ValueError("CompositeCPA without LocationCPA has no location")
        return state[self._location_index].node_id

    def get_component(self, cpa_type: type, state: AbstractState) -> Optional[AbstractState]:
        """Return the component state belonging to the CPA of ``cpa_type``."""
        for index, cpa in enumerate(self.cpas):
            if isinstance(cpa, cpa_type):
                return state[index]
        return None


# ---------------------------------------------------------------------------
# The CPA worklist algorithm
# ---------------------------------------------------------------------------


class ReachedSet:
    """Reached set partitioned by program location.

    Partitioning keeps merge and stop cheap: only states at the same location
    can ever cover or be merged with each other.
    """

    def __init__(self, key_function: Callable[[AbstractState], Any]):
        self._key = key_function
        self.partitions: dict[Any, set] = {}
        self.size = 0

    def add(self, state: AbstractState) -> None:
        partition = self.partitions.setdefault(self._key(state), set())
        if state not in partition:
            partition.add(state)
            self.size += 1

    def remove(self, state: AbstractState) -> None:
        partition = self.partitions.get(self._key(state))
        if partition and state in partition:
            partition.discard(state)
            self.size -= 1

    def get_reached_for(self, state: AbstractState) -> set:
        return self.partitions.get(self._key(state), set())

    def __iter__(self):
        for partition in self.partitions.values():
            for state in partition:
                yield state

    def __len__(self) -> int:
        return self.size


class AlgorithmResult:
    """Outcome of a run of :class:`CPAAlgorithm`."""

    def __init__(self) -> None:
        self.reached: Optional[ReachedSet] = None
        self.target_state: Optional[AbstractState] = None
        self.error_path: list[tuple[AbstractState, CFAEdge]] = []
        self.exhausted: bool = False   # state space completely explored
        self.timed_out: bool = False
        self.limit_reached: bool = False
        self.iterations: int = 0
        self.transfers: int = 0

    @property
    def is_sound_true(self) -> bool:
        return self.exhausted and self.target_state is None

    def __repr__(self) -> str:
        return (f"AlgorithmResult(target={self.target_state is not None}, "
                f"exhausted={self.exhausted}, iterations={self.iterations})")


class CPAAlgorithm:
    """Generic reachability algorithm parameterised by a CPA."""

    def __init__(self, cpa: ConfigurableProgramAnalysis, cfa: CFA,
                 timelimit: float = 900.0,
                 max_states: int = DEFAULT_MAX_STATES,
                 is_target: Optional[Callable[[int, AbstractState], bool]] = None,
                 stop_on_target: bool = True):
        self.cpa = cpa
        self.cfa = cfa
        self.timelimit = timelimit
        self.max_states = max_states
        self.stop_on_target = stop_on_target
        self._is_target = is_target
        self._deadline: Optional[float] = None

    # -- helpers --------------------------------------------------------
    def _location(self, state: AbstractState) -> int:
        return self.cpa.get_location(state)

    def _is_target_state(self, state: AbstractState) -> bool:
        location = self._location(state)
        if self._is_target is not None:
            return self._is_target(location, state)
        node = self.cfa.nodes.get(location)
        return bool(node is not None and node.is_error)

    def _build_path(self, state: AbstractState,
                    parents: dict) -> list[tuple[AbstractState, CFAEdge]]:
        path: list[tuple[AbstractState, CFAEdge]] = []
        current = state
        seen = set()
        while current in parents and id(current) not in seen:
            seen.add(id(current))
            predecessor, edge = parents[current]
            path.append((current, edge))
            current = predecessor
        path.append((current, None))
        path.reverse()
        return path

    # -- main loop ------------------------------------------------------
    def run(self, initial_states: Optional[Iterable[AbstractState]] = None) -> AlgorithmResult:
        result = AlgorithmResult()
        precision = self.cpa.get_initial_precision()

        if initial_states is None:
            initial_states = [self.cpa.get_initial_state(self.cfa.entry_node)]
        initial_states = list(initial_states)

        reached = ReachedSet(self._location)
        result.reached = reached
        waitlist: list[AbstractState] = []
        parents: dict[AbstractState, tuple[AbstractState, CFAEdge]] = {}

        for state in initial_states:
            reached.add(state)
            waitlist.append(state)

        self._deadline = time.time() + self.timelimit

        while waitlist:
            if result.iterations % 512 == 0 and time.time() > self._deadline:
                result.timed_out = True
                return result
            if len(reached) > self.max_states:
                result.limit_reached = True
                return result

            result.iterations += 1
            state = waitlist.pop()

            if self._is_target_state(state):
                result.target_state = state
                result.error_path = self._build_path(state, parents)
                if self.stop_on_target:
                    return result
                continue

            location = self._location(state)
            for edge in self.cfa.get_successors(location):
                result.transfers += 1
                successors = self.cpa.get_transfer_relation().get_abstract_successors(
                    state, precision, edge
                )
                for successor in successors:
                    # --- merge with the states already reached ---------
                    for other in list(reached.get_reached_for(successor)):
                        merged = self.cpa.get_merge_operator().merge(
                            successor, other, precision
                        )
                        if merged != other:
                            reached.remove(other)
                            reached.add(merged)
                            if other in waitlist:
                                waitlist.remove(other)
                            waitlist.append(merged)
                            parents[merged] = parents.get(other, (state, edge))

                    # --- coverage check -------------------------------
                    if not self.cpa.get_stop_operator().stop(
                        successor, reached.get_reached_for(successor), precision
                    ):
                        if successor not in parents:
                            parents[successor] = (state, edge)
                        reached.add(successor)
                        waitlist.append(successor)

        result.exhausted = True
        return result


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def describe_path(path: list[tuple[AbstractState, CFAEdge]]) -> list[str]:
    """Render a counterexample path as human readable lines."""
    lines: list[str] = []
    for state, edge in path:
        if edge is None:
            lines.append(f"init  {state}")
            continue
        if edge.edge_type is EdgeType.ASSIGNMENT:
            operation = f"{edge.variable} = {edge.expression}"
        elif edge.edge_type is EdgeType.ASSUME_TRUE:
            operation = f"[{edge.expression}]"
        elif edge.edge_type is EdgeType.ASSUME_FALSE:
            operation = f"[!({edge.expression})]"
        elif edge.edge_type is EdgeType.ASSERT:
            operation = "assertion violated"
        else:
            operation = edge.edge_type.value
        lines.append(f"N{edge.source} -> N{edge.target}: {operation}  {state}")
    return lines


def run_value_analysis(cfa: CFA, timelimit: float = 900.0) -> VerificationResult:
    """Verify ``cfa`` with LocationCPA x ExplicitValueCPA."""
    cpa = CompositeCPA([LocationCPA(cfa), ExplicitValueCPA(cfa)])
    algorithm = CPAAlgorithm(cpa, cfa, timelimit=timelimit)
    outcome = algorithm.run()

    statistics = {
        "analysis": "valueAnalysis",
        "reached states": len(outcome.reached) if outcome.reached else 0,
        "iterations": outcome.iterations,
        "transfer relation calls": outcome.transfers,
    }

    if outcome.target_state is not None:
        path = describe_path(outcome.error_path)
        statistics["counterexample length"] = len(path)
        statistics["counterexample"] = " | ".join(path)
        return VerificationResult(
            verdict=Verdict.FALSE,
            property_violated="assertion",
            error_path=path,
            statistics=statistics,
        )

    if outcome.exhausted:
        return VerificationResult(verdict=Verdict.TRUE, statistics=statistics)

    statistics["reason"] = "timeout" if outcome.timed_out else "state limit reached"
    return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

