"""Loop detection on the CFA: back edges, loop heads and natural loop bodies."""

from __future__ import annotations

from typing import Iterable, Optional

from cpachecker.cfa import CFA, CFAEdge


def _successors(cfa: CFA) -> dict[int, list[CFAEdge]]:
    outgoing: dict[int, list[CFAEdge]] = {node_id: [] for node_id in cfa.nodes}
    for edge in cfa.edges:
        outgoing.setdefault(edge.source, []).append(edge)
    return outgoing


def find_back_edges(cfa: CFA) -> list[CFAEdge]:
    """Return the back edges of a depth-first search from the entry node.

    An edge is a back edge when its target is still on the DFS stack, i.e. the
    edge closes a cycle.  Those targets are the loop heads of the CFA.
    """
    outgoing = _successors(cfa)
    back_edges: list[CFAEdge] = []
    on_stack: set[int] = set()
    finished: set[int] = set()

    # Iterative DFS: entries are (node, iterator over outgoing edges).
    roots = [cfa.entry_node] + [n for n in sorted(cfa.nodes) if n != cfa.entry_node]
    for root in roots:
        if root in finished or root not in cfa.nodes:
            continue
        stack: list[tuple[int, list[CFAEdge], int]] = [(root, outgoing.get(root, []), 0)]
        on_stack.add(root)
        while stack:
            node, edges, index = stack[-1]
            if index >= len(edges):
                stack.pop()
                on_stack.discard(node)
                finished.add(node)
                continue
            stack[-1] = (node, edges, index + 1)
            edge = edges[index]
            target = edge.target
            if target in on_stack:
                back_edges.append(edge)
            elif target not in finished and target in cfa.nodes:
                stack.append((target, outgoing.get(target, []), 0))
                on_stack.add(target)
    return back_edges


def find_loop_heads(cfa: CFA) -> set[int]:
    """Loop heads = targets of back edges (plus parser-annotated heads)."""
    heads = {edge.target for edge in find_back_edges(cfa)}
    for node in cfa.nodes.values():
        if node.label == "loop_head":
            heads.add(node.node_id)
    return heads


class LoopInfo:
    """A natural loop: its head, its body nodes and its edges."""

    __slots__ = ("head", "back_edges", "nodes", "body_edges", "entry_edges", "exit_edges")

    def __init__(self, head: int):
        self.head = head
        self.back_edges: list[CFAEdge] = []
        self.nodes: set[int] = {head}
        self.body_edges: list[CFAEdge] = []
        self.entry_edges: list[CFAEdge] = []
        self.exit_edges: list[CFAEdge] = []

    def __repr__(self) -> str:
        return f"Loop(head={self.head}, nodes={sorted(self.nodes)})"


def find_loops(cfa: CFA) -> dict[int, LoopInfo]:
    """Compute the natural loop for every loop head of the CFA."""
    back_edges = find_back_edges(cfa)
    incoming: dict[int, list[CFAEdge]] = {}
    for edge in cfa.edges:
        incoming.setdefault(edge.target, []).append(edge)

    loops: dict[int, LoopInfo] = {}
    for edge in back_edges:
        loop = loops.setdefault(edge.target, LoopInfo(edge.target))
        loop.back_edges.append(edge)
        # Collect all nodes that reach the back-edge source without passing
        # through the head: the classic natural-loop body computation.
        worklist = [edge.source]
        while worklist:
            node = worklist.pop()
            if node in loop.nodes:
                continue
            loop.nodes.add(node)
            for predecessor in incoming.get(node, []):
                worklist.append(predecessor.source)

    for loop in loops.values():
        for edge in cfa.edges:
            inside_source = edge.source in loop.nodes
            inside_target = edge.target in loop.nodes
            if inside_source and inside_target:
                loop.body_edges.append(edge)
            elif inside_target and not inside_source:
                loop.entry_edges.append(edge)
            elif inside_source and not inside_target:
                loop.exit_edges.append(edge)
    return loops


def is_back_edge(edge: CFAEdge, back_edges: Iterable[CFAEdge]) -> bool:
    return any(edge is other or (edge.source == other.source
                                 and edge.target == other.target)
               for other in back_edges)
