"""Simple C parser that builds a CFA from a subset of C.

Supported constructs:
- int/unsigned variable declarations with optional initialization
- Assignment statements (arithmetic: +, -, *, /, %)
- if/else statements
- while loops
- __VERIFIER_nondet_uint() for nondeterministic values
- __assert_fail() / assert() for assertions
- return statements
- Basic arithmetic and comparison operators
"""

import re
from typing import Optional

from cpachecker.cfa import CFA, CFAEdge, CFANode, EdgeType


class Token:
    def __init__(self, kind: str, value: str, line: int = 0):
        self.kind = kind
        self.value = value
        self.line = line

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r})"


TOKEN_PATTERNS = [
    ("COMMENT_LINE", r"//[^\n]*"),
    ("COMMENT_BLOCK", r"/\*[\s\S]*?\*/"),
    ("PREPROC", r"#[^\n]*"),
    ("KEYWORD", r"\b(int|unsigned|void|extern|if|else|while|for|return|const|char|static|switch|case|break|default)\b"),
    ("IDENT", r"[a-zA-Z_][a-zA-Z0-9_]*"),
    ("NUMBER", r"\b\d+[UuLl]?\b"),
    ("STRING", r'"[^"]*"'),
    ("OP", r"\+\+|--|[+\-*/%]=|[<>!=]=|&&|\|\||<<|>>|[+\-*/%<>=!&|^~]"),
    ("LPAREN", r"\("),
    ("RPAREN", r"\)"),
    ("LBRACE", r"\{"),
    ("RBRACE", r"\}"),
    ("LBRACKET", r"\["),
    ("RBRACKET", r"\]"),
    ("SEMI", r";"),
    ("COMMA", r","),
    ("DOT", r"\."),
    ("ARROW", r"->"),
    ("COLON", r":"),
    ("WS", r"\s+"),
]

TOKEN_RE = re.compile("|".join(f"(?P<{name}>{pat})" for name, pat in TOKEN_PATTERNS))


def tokenize(source: str) -> list[Token]:
    tokens = []
    line = 1
    for m in TOKEN_RE.finditer(source):
        kind = m.lastgroup
        value = m.group()
        if kind == "WS":
            line += value.count("\n")
            continue
        if kind in ("COMMENT_LINE", "COMMENT_BLOCK", "PREPROC"):
            line += value.count("\n")
            continue
        tokens.append(Token(kind, value, line))
    return tokens


class Parser:
    """Recursive-descent parser for simplified C → CFA."""

    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0
        self.node_counter = 0
        self.cfa = CFA()
        self.variables: list[str] = []

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, value: str = None) -> Token:
        tok = self.advance()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise SyntaxError(
                f"Expected ({kind}, {value}), got ({tok.kind}, {tok.value}) at line {tok.line}"
            )
        return tok

    def match(self, kind: str, value: str = None) -> Optional[Token]:
        tok = self.peek()
        if tok and tok.kind == kind and (value is None or tok.value == value):
            return self.advance()
        return None

    def new_node(self, label: str = "") -> int:
        nid = self.node_counter
        self.node_counter += 1
        self.cfa.add_node(CFANode(node_id=nid, label=label))
        return nid

    def parse(self) -> CFA:
        """Parse the entire program, return CFA for main function."""
        while self.pos < len(self.tokens):
            if self._is_function_def():
                self._parse_function()
            else:
                self._skip_declaration()
        self.cfa.variables = self.variables
        return self.cfa

    def _is_function_def(self) -> bool:
        save = self.pos
        try:
            while self.peek() and self.peek().kind == "KEYWORD":
                self.advance()
            if self.peek() and self.peek().kind == "IDENT":
                self.advance()
                if self.peek() and self.peek().kind == "LPAREN":
                    self.pos = save
                    return True
        except (IndexError, AttributeError):
            pass
        self.pos = save
        return False

    def _skip_declaration(self):
        depth = 0
        while self.pos < len(self.tokens):
            tok = self.advance()
            if tok.kind == "LBRACE":
                depth += 1
            elif tok.kind == "RBRACE":
                depth -= 1
                if depth <= 0:
                    return
            elif tok.kind == "SEMI" and depth == 0:
                return

    def _parse_function(self):
        while self.peek() and self.peek().kind == "KEYWORD":
            self.advance()
        name_tok = self.expect("IDENT")

        self.expect("LPAREN")
        depth = 1
        while depth > 0:
            t = self.advance()
            if t.kind == "LPAREN":
                depth += 1
            elif t.kind == "RPAREN":
                depth -= 1

        if self.peek() and self.peek().kind == "SEMI":
            self.advance()
            return

        self.expect("LBRACE")
        self.cfa.function_name = name_tok.value

        if name_tok.value == "main":
            entry = self.new_node("entry")
            self.cfa.entry_node = entry
            self.cfa.nodes[entry].is_entry = True
            exit_node = self.new_node("exit")
            self.cfa.exit_node = exit_node
            self.cfa.nodes[exit_node].is_exit = True
            self._parse_block(entry, exit_node)
        else:
            self._skip_brace_block()

    def _skip_brace_block(self):
        depth = 1
        while depth > 0:
            t = self.advance()
            if t.kind == "LBRACE":
                depth += 1
            elif t.kind == "RBRACE":
                depth -= 1

    def _parse_block(self, entry: int, exit_node: int):
        current = entry
        while self.peek() and self.peek().kind != "RBRACE":
            current = self._parse_statement(current, exit_node)
        self.expect("RBRACE")
        if current != exit_node:
            self.cfa.add_edge(CFAEdge(current, exit_node, EdgeType.BLANK))

    def _parse_statement(self, current: int, exit_node: int) -> int:
        tok = self.peek()
        if tok is None:
            return current

        if tok.kind == "KEYWORD" and tok.value in ("int", "unsigned", "const"):
            return self._parse_var_decl(current)
        elif tok.kind == "KEYWORD" and tok.value == "if":
            return self._parse_if(current, exit_node)
        elif tok.kind == "KEYWORD" and tok.value == "while":
            return self._parse_while(current, exit_node)
        elif tok.kind == "KEYWORD" and tok.value == "for":
            return self._parse_for(current, exit_node)
        elif tok.kind == "KEYWORD" and tok.value == "return":
            return self._parse_return(current, exit_node)
        elif tok.kind == "LBRACE":
            self.advance()
            next_node = self.new_node()
            self._parse_block(current, next_node)
            return next_node
        elif tok.kind == "IDENT":
            return self._parse_expr_statement(current)
        else:
            self.advance()
            return current

    def _parse_var_decl(self, current: int) -> int:
        while self.peek() and self.peek().kind == "KEYWORD":
            self.advance()
        var_name = self.expect("IDENT").value
        if var_name not in self.variables:
            self.variables.append(var_name)

        if self.match("OP", "="):
            expr = self._collect_expression()
            next_node = self.new_node()
            self.cfa.add_edge(
                CFAEdge(current, next_node, EdgeType.ASSIGNMENT,
                        expression=expr, variable=var_name)
            )
            current = next_node
        self.expect("SEMI")
        return current

    def _parse_expr_statement(self, current: int) -> int:
        ident = self.advance()
        if self.peek() and self.peek().kind == "LPAREN":
            func_call = ident.value + self._collect_parens()
            if "__assert_fail" in ident.value:
                error_node = self.new_node("error")
                self.cfa.nodes[error_node].is_error = True
                self.cfa.add_edge(
                    CFAEdge(current, error_node, EdgeType.ASSERT, expression=func_call)
                )
                self.expect("SEMI")
                return self.new_node()
            else:
                next_node = self.new_node()
                self.cfa.add_edge(
                    CFAEdge(current, next_node, EdgeType.FUNCTION_CALL, expression=func_call)
                )
                self.expect("SEMI")
                return next_node
        elif self.peek() and self.peek().kind == "OP":
            op = self.advance().value
            if op == "=" or op.endswith("="):
                expr = self._collect_expression()
                if op != "=":
                    base_op = op[:-1]
                    expr = f"{ident.value} {base_op} ({expr})"
                next_node = self.new_node()
                self.cfa.add_edge(
                    CFAEdge(current, next_node, EdgeType.ASSIGNMENT,
                            expression=expr, variable=ident.value)
                )
                self.expect("SEMI")
                return next_node
            elif op in ("++", "--"):
                expr = f"{ident.value} + 1" if op == "++" else f"{ident.value} - 1"
                next_node = self.new_node()
                self.cfa.add_edge(
                    CFAEdge(current, next_node, EdgeType.ASSIGNMENT,
                            expression=expr, variable=ident.value)
                )
                self.expect("SEMI")
                return next_node
        self._skip_to_semi()
        return current

    def _parse_if(self, current: int, exit_node: int) -> int:
        self.expect("KEYWORD", "if")
        self.expect("LPAREN")
        cond = self._collect_until_rparen()

        true_entry = self.new_node()
        self.cfa.add_edge(
            CFAEdge(current, true_entry, EdgeType.ASSUME_TRUE, expression=cond)
        )

        merge_node = self.new_node("merge")

        if self.peek() and self.peek().kind == "LBRACE":
            self.advance()
            self._parse_block(true_entry, merge_node)
        else:
            end = self._parse_statement(true_entry, exit_node)
            if end != merge_node:
                self.cfa.add_edge(CFAEdge(end, merge_node, EdgeType.BLANK))

        if self.match("KEYWORD", "else"):
            false_entry = self.new_node()
            self.cfa.add_edge(
                CFAEdge(current, false_entry, EdgeType.ASSUME_FALSE, expression=cond)
            )
            if self.peek() and self.peek().kind == "LBRACE":
                self.advance()
                self._parse_block(false_entry, merge_node)
            else:
                end = self._parse_statement(false_entry, exit_node)
                if end != merge_node:
                    self.cfa.add_edge(CFAEdge(end, merge_node, EdgeType.BLANK))
        else:
            self.cfa.add_edge(
                CFAEdge(current, merge_node, EdgeType.ASSUME_FALSE, expression=cond)
            )

        return merge_node

    def _parse_while(self, current: int, exit_node: int) -> int:
        self.expect("KEYWORD", "while")
        self.expect("LPAREN")
        cond = self._collect_until_rparen()

        loop_head = self.new_node("loop_head")
        self.cfa.add_edge(CFAEdge(current, loop_head, EdgeType.BLANK))

        body_entry = self.new_node()
        self.cfa.add_edge(
            CFAEdge(loop_head, body_entry, EdgeType.ASSUME_TRUE, expression=cond)
        )

        loop_exit = self.new_node()
        self.cfa.add_edge(
            CFAEdge(loop_head, loop_exit, EdgeType.ASSUME_FALSE, expression=cond)
        )

        if self.peek() and self.peek().kind == "LBRACE":
            self.advance()
            self._parse_block(body_entry, loop_head)
        else:
            end = self._parse_statement(body_entry, exit_node)
            if end != loop_head:
                self.cfa.add_edge(CFAEdge(end, loop_head, EdgeType.BLANK))

        return loop_exit

    def _parse_for(self, current: int, exit_node: int) -> int:
        self.expect("KEYWORD", "for")
        self.expect("LPAREN")
        init_expr = self._collect_until_semi_in_for()
        if init_expr.strip():
            next_node = self.new_node()
            parts = init_expr.strip().split("=", 1)
            if len(parts) == 2:
                var = parts[0].strip().split()[-1]
                expr = parts[1].strip()
                if var not in self.variables:
                    self.variables.append(var)
                self.cfa.add_edge(
                    CFAEdge(current, next_node, EdgeType.ASSIGNMENT,
                            expression=expr, variable=var)
                )
            else:
                self.cfa.add_edge(CFAEdge(current, next_node, EdgeType.BLANK))
            current = next_node

        cond = self._collect_until_semi_in_for()
        update = self._collect_until_rparen()

        loop_head = self.new_node("loop_head")
        self.cfa.add_edge(CFAEdge(current, loop_head, EdgeType.BLANK))

        body_entry = self.new_node()
        self.cfa.add_edge(
            CFAEdge(loop_head, body_entry, EdgeType.ASSUME_TRUE, expression=cond)
        )
        loop_exit = self.new_node()
        self.cfa.add_edge(
            CFAEdge(loop_head, loop_exit, EdgeType.ASSUME_FALSE, expression=cond)
        )

        update_node = self.new_node("update")

        if self.peek() and self.peek().kind == "LBRACE":
            self.advance()
            self._parse_block(body_entry, update_node)
        else:
            end = self._parse_statement(body_entry, exit_node)
            if end != update_node:
                self.cfa.add_edge(CFAEdge(end, update_node, EdgeType.BLANK))

        if update.strip():
            update = update.strip().rstrip(";")
            if "++" in update:
                var = update.replace("++", "").strip()
                self.cfa.add_edge(
                    CFAEdge(update_node, loop_head, EdgeType.ASSIGNMENT,
                            expression=f"{var} + 1", variable=var)
                )
            elif "--" in update:
                var = update.replace("--", "").strip()
                self.cfa.add_edge(
                    CFAEdge(update_node, loop_head, EdgeType.ASSIGNMENT,
                            expression=f"{var} - 1", variable=var)
                )
            else:
                self.cfa.add_edge(CFAEdge(update_node, loop_head, EdgeType.BLANK))
        else:
            self.cfa.add_edge(CFAEdge(update_node, loop_head, EdgeType.BLANK))

        return loop_exit

    def _parse_return(self, current: int, exit_node: int) -> int:
        self.advance()
        self._skip_to_semi()
        self.cfa.add_edge(CFAEdge(current, exit_node, EdgeType.BLANK))
        return exit_node

    def _collect_expression(self) -> str:
        parts = []
        depth = 0
        while self.peek():
            tok = self.peek()
            if tok.kind == "SEMI" and depth == 0:
                break
            if tok.kind == "LPAREN":
                depth += 1
            elif tok.kind == "RPAREN":
                depth -= 1
                if depth < 0:
                    break
            parts.append(self.advance().value)
        return " ".join(parts)

    def _collect_until_rparen(self) -> str:
        parts = []
        depth = 0
        while self.peek():
            tok = self.peek()
            if tok.kind == "RPAREN" and depth == 0:
                self.advance()
                break
            if tok.kind == "LPAREN":
                depth += 1
            elif tok.kind == "RPAREN":
                depth -= 1
            parts.append(self.advance().value)
        return " ".join(parts)

    def _collect_until_semi_in_for(self) -> str:
        parts = []
        depth = 0
        while self.peek():
            tok = self.peek()
            if tok.kind == "SEMI" and depth == 0:
                self.advance()
                break
            if tok.kind == "LPAREN":
                depth += 1
            elif tok.kind == "RPAREN":
                depth -= 1
            parts.append(self.advance().value)
        return " ".join(parts)

    def _collect_parens(self) -> str:
        self.expect("LPAREN")
        parts = ["("]
        depth = 1
        while depth > 0:
            tok = self.advance()
            if tok.kind == "LPAREN":
                depth += 1
            elif tok.kind == "RPAREN":
                depth -= 1
            parts.append(tok.value)
        return "".join(parts)

    def _skip_to_semi(self):
        depth = 0
        while self.pos < len(self.tokens):
            tok = self.tokens[self.pos]
            if tok.kind == "SEMI" and depth == 0:
                self.pos += 1
                return
            if tok.kind == "LPAREN":
                depth += 1
            elif tok.kind == "RPAREN":
                depth -= 1
            self.pos += 1


def parse_c_file(filepath: str) -> CFA:
    """Parse a C file and return its CFA."""
    with open(filepath, "r") as f:
        source = f.read()
    tokens = tokenize(source)
    parser = Parser(tokens)
    cfa = parser.parse()
    cfa.program_path = filepath  # type: ignore[attr-defined]
    return cfa

