"""Parsing of C expressions and their translation into linear constraints.

The CFA stores the source text of expressions on its edges.  The symbolic
analyses need those expressions as terms of linear integer arithmetic, so this
module provides

* a small recursive-descent parser producing an expression AST,
* :class:`SymbolicEncoder`, which turns an AST into a :class:`LinExpr` (for
  assignments) or into a list of constraints (for assume edges) relative to a
  symbolic environment mapping program variables to affine expressions.

Constructs that cannot be expressed in linear integer arithmetic (products of
two unknowns, division by an unknown, ...) are replaced by a fresh
unconstrained symbol.  That is an over-approximation: the analysis may consider
more behaviours than the program has, but never fewer.
"""

from __future__ import annotations

import re
from typing import Iterable, Optional

from cpachecker.analyses.linear_arithmetic import (
    Clause,
    Constraint,
    LinExpr,
    NonLinearError,
    ONE,
)

_TOKEN_RE = re.compile(r"""
      (?P<number>\b\d+[uUlL]*\b)
    | (?P<ident>[A-Za-z_]\w*)
    | (?P<op><<|>>|<=|>=|==|!=|&&|\|\||[-+*/%<>!()~&|^,])
    | (?P<space>\s+)
    | (?P<other>.)
""", re.VERBOSE)


class ExpressionSyntaxError(Exception):
    """The expression text is not supported by the simplified parser."""


# ---------------------------------------------------------------------------
# AST
# ---------------------------------------------------------------------------


class Expr:
    """Base class of expression AST nodes."""

    def variables(self) -> set[str]:
        return set()


class Num(Expr):
    __slots__ = ("value",)

    def __init__(self, value: int):
        self.value = value

    def __repr__(self) -> str:
        return str(self.value)


class Var(Expr):
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name

    def variables(self) -> set[str]:
        return {self.name}

    def __repr__(self) -> str:
        return self.name


class Call(Expr):
    __slots__ = ("name", "arguments")

    def __init__(self, name: str, arguments: list[Expr]):
        self.name = name
        self.arguments = arguments

    def variables(self) -> set[str]:
        found: set[str] = set()
        for argument in self.arguments:
            found |= argument.variables()
        return found

    def __repr__(self) -> str:
        return f"{self.name}({', '.join(repr(a) for a in self.arguments)})"


class Unary(Expr):
    __slots__ = ("operator", "operand")

    def __init__(self, operator: str, operand: Expr):
        self.operator = operator
        self.operand = operand

    def variables(self) -> set[str]:
        return self.operand.variables()

    def __repr__(self) -> str:
        return f"{self.operator}({self.operand!r})"


class Binary(Expr):
    __slots__ = ("operator", "left", "right")

    def __init__(self, operator: str, left: Expr, right: Expr):
        self.operator = operator
        self.left = left
        self.right = right

    def variables(self) -> set[str]:
        return self.left.variables() | self.right.variables()

    def __repr__(self) -> str:
        return f"({self.left!r} {self.operator} {self.right!r})"


COMPARISONS = ("==", "!=", "<", "<=", ">", ">=")


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------


class ExpressionParser:
    """Recursive-descent parser for the C expression subset we support."""

    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.position = 0

    @staticmethod
    def _tokenize(text: str) -> list[str]:
        tokens: list[str] = []
        for match in _TOKEN_RE.finditer(text):
            kind = match.lastgroup
            value = match.group()
            if kind == "space":
                continue
            if kind == "other":
                if value.strip('"') != value or value in ('"', "'"):
                    raise ExpressionSyntaxError(f"unsupported token {value!r}")
                raise ExpressionSyntaxError(f"unsupported token {value!r}")
            tokens.append(value)
        return tokens

    # -- helpers --------------------------------------------------------
    def peek(self) -> Optional[str]:
        if self.position < len(self.tokens):
            return self.tokens[self.position]
        return None

    def advance(self) -> str:
        token = self.tokens[self.position]
        self.position += 1
        return token

    def accept(self, *values: str) -> Optional[str]:
        if self.peek() in values:
            return self.advance()
        return None

    def expect(self, value: str) -> None:
        if self.accept(value) is None:
            raise ExpressionSyntaxError(f"expected {value!r} in {' '.join(self.tokens)!r}")

    # -- grammar --------------------------------------------------------
    def parse(self) -> Expr:
        if not self.tokens:
            raise ExpressionSyntaxError("empty expression")
        node = self._parse_or()
        if self.position != len(self.tokens):
            raise ExpressionSyntaxError(
                f"trailing tokens in {' '.join(self.tokens)!r}")
        return node

    def _parse_or(self) -> Expr:
        node = self._parse_and()
        while self.accept("||"):
            node = Binary("||", node, self._parse_and())
        return node

    def _parse_and(self) -> Expr:
        node = self._parse_equality()
        while self.accept("&&"):
            node = Binary("&&", node, self._parse_equality())
        return node

    def _parse_equality(self) -> Expr:
        node = self._parse_relational()
        while True:
            operator = self.accept("==", "!=")
            if operator is None:
                return node
            node = Binary(operator, node, self._parse_relational())

    def _parse_relational(self) -> Expr:
        node = self._parse_additive()
        while True:
            operator = self.accept("<", "<=", ">", ">=")
            if operator is None:
                return node
            node = Binary(operator, node, self._parse_additive())

    def _parse_additive(self) -> Expr:
        node = self._parse_multiplicative()
        while True:
            operator = self.accept("+", "-")
            if operator is None:
                return node
            node = Binary(operator, node, self._parse_multiplicative())

    def _parse_multiplicative(self) -> Expr:
        node = self._parse_unary()
        while True:
            operator = self.accept("*", "/", "%")
            if operator is None:
                return node
            node = Binary(operator, node, self._parse_unary())

    def _parse_unary(self) -> Expr:
        operator = self.accept("-", "+", "!", "~")
        if operator is not None:
            operand = self._parse_unary()
            if operator == "+":
                return operand
            return Unary(operator, operand)
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        token = self.peek()
        if token is None:
            raise ExpressionSyntaxError("unexpected end of expression")
        if token == "(":
            self.advance()
            node = self._parse_or()
            self.expect(")")
            return node
        if re.fullmatch(r"\d+[uUlL]*", token):
            self.advance()
            return Num(int(token.rstrip("uUlL")))
        if re.fullmatch(r"[A-Za-z_]\w*", token):
            self.advance()
            if self.peek() == "(":
                self.advance()
                arguments: list[Expr] = []
                if self.peek() != ")":
                    arguments.append(self._parse_or())
                    while self.accept(","):
                        arguments.append(self._parse_or())
                self.expect(")")
                return Call(token, arguments)
            return Var(token)
        raise ExpressionSyntaxError(f"unexpected token {token!r}")


_PARSE_CACHE: dict[str, Expr] = {}


def parse_expression(text: str) -> Expr:
    """Parse an expression, caching the result (edges are visited often)."""
    cached = _PARSE_CACHE.get(text)
    if cached is None:
        cached = ExpressionParser(text).parse()
        _PARSE_CACHE[text] = cached
    return cached


def collect_atoms(node: Expr) -> list[Expr]:
    """Collect the atomic (comparison) sub-expressions of a condition."""
    if isinstance(node, Binary) and node.operator in ("&&", "||"):
        return collect_atoms(node.left) + collect_atoms(node.right)
    if isinstance(node, Unary) and node.operator == "!":
        return collect_atoms(node.operand)
    return [node]


def is_nondet_call(node: Expr) -> bool:
    return isinstance(node, Call) and node.name.startswith("__VERIFIER_nondet")


def contains_nondet(node: Expr) -> bool:
    if is_nondet_call(node):
        return True
    if isinstance(node, Unary):
        return contains_nondet(node.operand)
    if isinstance(node, Binary):
        return contains_nondet(node.left) or contains_nondet(node.right)
    if isinstance(node, Call):
        return any(contains_nondet(a) for a in node.arguments)
    return False


# ---------------------------------------------------------------------------
# Encoding into linear arithmetic
# ---------------------------------------------------------------------------


class SymbolFactory:
    """Supplies fresh symbol names for nondeterministic/opaque values."""

    __slots__ = ("counter",)

    def __init__(self) -> None:
        self.counter = 0

    def fresh(self, hint: str = "s") -> str:
        self.counter += 1
        return f"{hint}@{self.counter}"


class SymbolicEncoder:
    """Translates expression ASTs into linear expressions and constraints.

    ``side_constraints`` accumulates definitional constraints created while
    encoding (for instance the auxiliary variable of a ``%`` operation).  The
    caller has to add them to the path formula.
    """

    def __init__(self, symbols: SymbolFactory):
        self.symbols = symbols

    # -- terms ----------------------------------------------------------
    def encode_term(self, node: Expr, environment: dict[str, LinExpr],
                    side_constraints: list) -> LinExpr:
        if isinstance(node, Num):
            return LinExpr.value(node.value)
        if isinstance(node, Var):
            existing = environment.get(node.name)
            if existing is None:
                # An unknown variable behaves like an unconstrained input.
                existing = LinExpr.symbol(self.symbols.fresh(node.name))
                environment[node.name] = existing
            return existing
        if isinstance(node, Call):
            return LinExpr.symbol(self.symbols.fresh("nondet"))
        if isinstance(node, Unary):
            if node.operator == "-":
                return -self.encode_term(node.operand, environment, side_constraints)
            if node.operator == "!":
                # !e is 1 when e == 0 and 0 otherwise: encode with a fresh flag.
                return self._encode_boolean_value(
                    Binary("==", node.operand, Num(0)), environment, side_constraints)
            return LinExpr.symbol(self.symbols.fresh("bit"))
        if isinstance(node, Binary):
            operator = node.operator
            if operator in COMPARISONS or operator in ("&&", "||"):
                return self._encode_boolean_value(node, environment, side_constraints)
            left = self.encode_term(node.left, environment, side_constraints)
            right = self.encode_term(node.right, environment, side_constraints)
            if operator == "+":
                return left + right
            if operator == "-":
                return left - right
            if operator == "*":
                try:
                    return left.multiply(right)
                except NonLinearError:
                    return LinExpr.symbol(self.symbols.fresh("mul"))
            if operator == "/":
                try:
                    return left.divide(right)
                except NonLinearError:
                    return LinExpr.symbol(self.symbols.fresh("div"))
            if operator == "%":
                return self._encode_modulo(left, right, side_constraints)
            # Bit operations are not modelled precisely.
            return LinExpr.symbol(self.symbols.fresh("bits"))
        raise ExpressionSyntaxError(f"cannot encode {node!r}")

    def _encode_modulo(self, left: LinExpr, right: LinExpr,
                       side_constraints: list) -> LinExpr:
        if left.is_constant and right.is_constant and right.constant != 0:
            modulus = abs(right.constant)
            remainder = abs(left.constant) % modulus
            return LinExpr.value(-remainder if left.constant < 0 else remainder)
        if not right.is_constant or right.constant == 0:
            return LinExpr.symbol(self.symbols.fresh("mod"))

        modulus = abs(right.constant)
        result = LinExpr.symbol(self.symbols.fresh("rem"))
        # (left - result) is a multiple of the modulus ...
        side_constraints.append(Constraint.congruent(left - result, modulus))
        # ... and C's remainder has the sign of the dividend, with
        # |result| < modulus.
        bound = LinExpr.value(modulus - 1)
        side_constraints.append(Clause([
            [Constraint.at_least_zero(result),
             Constraint.at_least_zero(bound - result),
             Constraint.at_least_zero(left)],
            [Constraint.at_least_zero(-result),
             Constraint.at_least_zero(bound + result),
             Constraint.at_least_zero(-left)],
        ]))
        return result

    def _encode_boolean_value(self, node: Expr, environment: dict[str, LinExpr],
                              side_constraints: list) -> LinExpr:
        """Encode a condition used as a value (0 or 1)."""
        flag = LinExpr.symbol(self.symbols.fresh("flag"))
        positive = self.encode_condition(node, environment, True, side_constraints)
        negative = self.encode_condition(node, environment, False, side_constraints)
        side_constraints.append(Clause([
            [Constraint.equal(flag - ONE)] + _flatten(positive),
            [Constraint.equal(flag)] + _flatten(negative),
        ]))
        return flag

    # -- conditions -----------------------------------------------------
    def encode_condition(self, node: Expr, environment: dict[str, LinExpr],
                         positive: bool, side_constraints: list) -> list:
        """Encode ``node`` (or its negation) as a conjunction of items."""
        if isinstance(node, Unary) and node.operator == "!":
            return self.encode_condition(node.operand, environment, not positive,
                                         side_constraints)
        if isinstance(node, Binary) and node.operator in ("&&", "||"):
            conjunctive = (node.operator == "&&") == positive
            left = self.encode_condition(node.left, environment, positive,
                                         side_constraints)
            right = self.encode_condition(node.right, environment, positive,
                                          side_constraints)
            if conjunctive:
                return left + right
            return [Clause([_flatten(left), _flatten(right)])]
        if isinstance(node, Binary) and node.operator in COMPARISONS:
            left = self.encode_term(node.left, environment, side_constraints)
            right = self.encode_term(node.right, environment, side_constraints)
            return _comparison_items(node.operator, left, right, positive)
        # Any other expression is a condition "value != 0".
        term = self.encode_term(node, environment, side_constraints)
        if positive:
            return [Clause([[Constraint.greater_zero(term)],
                            [Constraint.greater_zero(-term)]])]
        return [Constraint.equal(term)]


def _flatten(items: Iterable) -> list[Constraint]:
    """Turn a conjunction of items into a flat constraint list.

    Nested disjunctions cannot be represented inside a clause alternative, so
    they are (soundly) weakened by dropping them.
    """
    flat: list[Constraint] = []
    for item in items:
        if isinstance(item, Constraint):
            flat.append(item)
        elif isinstance(item, Clause) and item.is_unit:
            flat.extend(item.alternatives[0])
    return flat


def _comparison_items(operator: str, left: LinExpr, right: LinExpr,
                      positive: bool) -> list:
    """Encode ``left <op> right`` (or its negation) as formula items."""
    if not positive:
        operator = {"==": "!=", "!=": "==", "<": ">=", ">=": "<",
                    ">": "<=", "<=": ">"}[operator]
    difference = left - right
    if operator == "==":
        return [Constraint.equal(difference)]
    if operator == "!=":
        return [Clause([[Constraint.greater_zero(difference)],
                        [Constraint.greater_zero(-difference)]])]
    if operator == "<":
        return [Constraint.greater_zero(-difference)]
    if operator == "<=":
        return [Constraint.at_least_zero(-difference)]
    if operator == ">":
        return [Constraint.greater_zero(difference)]
    if operator == ">=":
        return [Constraint.at_least_zero(difference)]
    raise ExpressionSyntaxError(f"unknown comparison {operator}")

