content.content:
"""Predicate analysis: symbolic path formulas with feasibility checking.

Instead of concrete values (see :mod:`cpachecker.analyses.value_analysis`) this
analysis tracks *symbolic* knowledge:

* every program variable is mapped to an affine term over symbols
  (``x -> nondet@2 - 1``), which is the strongest postcondition of the
  assignments seen along the path, and
* the path constraints collected from the assume edges.

Whenever an assume edge is processed the resulting constraint set is handed to
the :class:`PathFeasibilityChecker`; infeasible paths are pruned immediately,
which is what makes the analysis able to verify programs over
nondeterministic inputs.

To obtain a *terminating* analysis for programs with loops, the precise path
formula is abstracted at loop heads (adjustable-block encoding): only those
predicates of a finite basis that are entailed by the path formula are kept.
The basis is derived from the program itself (the atoms of all assume edges
and the equalities induced by assignments) and can be extended by a
counterexample-guided refinement step.
"""

from __future__ import annotations

import time
from typing import Iterable, Optional, Sequence

from cpachecker.analyses.linear_arithmetic import (
    Clause,
    Constraint,
    LinExpr,
    NonLinearError,
    SolverLimits,
    entails,
    find_model,
    is_satisfiable,
    negate_items,
)
from cpachecker.analyses.loops import find_loop_heads
from cpachecker.analyses.symbolic_expressions import (
    Binary,
    Expr,
    ExpressionSyntaxError,
    Num,
    SymbolFactory,
    SymbolicEncoder,
    Unary,
    Var,
    Call,
    collect_atoms,
    contains_nondet,
    parse_expression,
)
from cpachecker.analyses.value_analysis import (
    CPAAlgorithm,
    CompositeCPA,
    LocationCPA,
    SepMergeOperator,
    SingletonPrecision,
    describe_path,
)
from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.result import Verdict, VerificationResult

MAX_REFINEMENTS = 3
MAX_PREDICATE_STATES = 60000


# ---------------------------------------------------------------------------
# Predicates
# ---------------------------------------------------------------------------


class Predicate:
    """An atomic condition (or its negation) used as abstraction predicate."""

    __slots__ = ("ast", "positive", "key")

    def __init__(self, ast: Expr, positive: bool = True):
        self.ast = ast
        self.positive = positive
        self.key = (repr(ast), positive)

    def encode(self, encoder: SymbolicEncoder, environment: dict[str, LinExpr],
               side_constraints: list) -> list:
        return encoder.encode_condition(self.ast, environment, self.positive,
                                        side_constraints)

    def encode_negation(self, encoder: SymbolicEncoder,
                        environment: dict[str, LinExpr],
                        side_constraints: list) -> list:
        return encoder.encode_condition(self.ast, environment, not self.positive,
                                        side_constraints)

    def variables(self) -> set[str]:
        return self.ast.variables()

    def __eq__(self, other) -> bool:
        return isinstance(other, Predicate) and other.key == self.key

    def __hash__(self) -> int:
        return hash(self.key)

    def __repr__(self) -> str:
        return repr(self.ast) if self.positive else f"!{self.ast!r}"


def sorted_predicates(predicates: Iterable[Predicate]) -> tuple:
    """Deterministic order (frozenset iteration order is not stable)."""
    return tuple(sorted(set(predicates), key=lambda p: p.key))


def substitute_ast(node: Expr, mapping: dict[str, Expr]) -> Expr:
    """Replace variables by expressions inside an AST (used for refinement)."""
    if isinstance(node, Var):
        return mapping.get(node.name, node)
    if isinstance(node, Num):
        return node
    if isinstance(node, Unary):
        return Unary(node.operator, substitute_ast(node.operand, mapping))
    if isinstance(node, Binary):
        return Binary(node.operator, substitute_ast(node.left, mapping),
                      substitute_ast(node.right, mapping))
    if isinstance(node, Call):
        return Call(node.name, [substitute_ast(a, mapping) for a in node.arguments])
    return node


# ---------------------------------------------------------------------------
# Constraint solving front-end
# ---------------------------------------------------------------------------


class PathFeasibilityChecker:
    """Maintains a set of linear constraints and answers SAT/UNSAT queries.

    The checker is a thin, memoising front-end for
    :mod:`cpachecker.analyses.linear_arithmetic`: equality reasoning (Gaussian
    elimination), interval propagation, Fourier-Motzkin elimination and modular
    (congruence) reasoning.
    """

    SAT = "SAT"
    UNSAT = "UNSAT"

    def __init__(self, limits: Optional[SolverLimits] = None):
        self.limits = limits or SolverLimits()
        self.constraints: list = []
        self.queries = 0
        self.cache_hits = 0
        self.unsat_results = 0
        self._cache: dict[tuple, str] = {}

    # -- the maintained constraint set ----------------------------------
    def add(self, item) -> None:
        self.constraints.append(item)

    def add_all(self, items: Iterable) -> None:
        self.constraints.extend(items)

    def reset(self, items: Iterable = ()) -> None:
        self.constraints = list(items)

    def check(self) -> str:
        """SAT/UNSAT for the currently maintained constraint set."""
        return self.check_items(self.constraints)

    # -- stateless queries ----------------------------------------------
    def check_items(self, items: Sequence) -> str:
        key = tuple(items)
        cached = self._cache.get(key)
        if cached is not None:
            self.cache_hits += 1
            return cached
        self.queries += 1
        verdict = self.SAT if is_satisfiable(key, self.limits) else self.UNSAT
        if verdict == self.UNSAT:
            self.unsat_results += 1
        if len(self._cache) < 100000:
            self._cache[key] = verdict
        return verdict

    def is_feasible(self, items: Sequence) -> bool:
        return self.check_items(items) == self.SAT

    def is_infeasible(self, items: Sequence) -> bool:
        return self.check_items(items) == self.UNSAT

    def implies(self, items: Sequence, consequence: Sequence) -> bool:
        """Check whether ``items`` logically implies ``consequence``."""
        negated = negate_items(list(consequence))
        if negated.is_false:
            return True
        return self.is_infeasible(list(items) + [negated])

    def statistics(self) -> dict:
        return {
            "solver queries": self.queries,
            "solver cache hits": self.cache_hits,
            "solver unsat results": self.unsat_results,
        }


def simplify_items(items: Iterable) -> Optional[list]:
    """Drop trivially true items; return ``None`` if an item is false."""
    result: list = []
    for item in items:
        if isinstance(item, Constraint):
            if item.expr.is_constant:
                constant = item.expr.constant
                if item.kind == Constraint.EQ and constant != 0:
                    return None
                if item.kind == Constraint.GEQ and constant < 0:
                    return None
                if (item.kind == Constraint.MOD and item.modulus > 1
                        and constant % item.modulus != 0):
                    return None
                continue                      # trivially true
            result.append(item)
        else:
            if item.is_false:
                return None
            if item.is_unit:
                nested = simplify_items(item.alternatives[0])
                if nested is None:
                    return None
                result.extend(nested)
                continue
            result.append(item)
    return list(dict.fromkeys(result))


# ---------------------------------------------------------------------------
# Abstract state
# ---------------------------------------------------------------------------


class PredicateAbstractState(AbstractState):
    """Symbolic environment plus a set of path constraints."""

    __slots__ = ("environment", "items", "predicates", "abstracted", "_key", "_hash")

    def __init__(self, environment: dict[str, LinExpr], items: Iterable = (),
                 predicates: Iterable[Predicate] = (), abstracted: bool = False):
        self.environment = dict(environment)
        self.items = tuple(items)
        self.predicates = frozenset(predicates)
        self.abstracted = abstracted
        if abstracted:
            # Abstract states are canonical: the predicate set identifies them.
            self._key = ("abstract", tuple(sorted(p.key for p in self.predicates)))
        else:
            self._key = ("path",
                         tuple(sorted((v, repr(e)) for v, e in self.environment.items())),
                         self.items)
        self._hash = hash(self._key)

    # -- queries --------------------------------------------------------
    def value_of(self, variable: str) -> Optional[LinExpr]:
        return self.environment.get(variable)

    def formula(self) -> list:
        return list(self.items)

    def is_less_or_equal(self, other: "PredicateAbstractState") -> bool:
        if self._key == other._key:
            return True
        if self.abstracted and other.abstracted:
            # A state with more predicates is stronger, hence covered.
            return other.predicates <= self.predicates
        return False

    def __eq__(self, other) -> bool:
        return isinstance(other, PredicateAbstractState) and other._key == self._key

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        if self.abstracted:
            predicates = ", ".join(repr(p) for p in sorted(self.predicates,
                                                           key=lambda p: p.key))
            return f"<abs {predicates or 'true'}>"
        assignments = ", ".join(f"{v}={e}" for v, e in sorted(self.environment.items()))
        constraints = ", ".join(repr(i) for i in self.items)
        return f"<{assignments} | {constraints}>"


class PredicateDomain(AbstractDomain):
    """Lattice of predicate states (implication ordering, approximated)."""

    def __init__(self, variables: Sequence[str]):
        self.variables = list(variables)

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        return state1.is_less_or_equal(state2)

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        if state1 == state2:
            return state1
        if state1.abstracted and state2.abstracted:
            common = state1.predicates & state2.predicates
            items = [i for i in state1.items if i in set(state2.items)]
            return PredicateAbstractState(state1.environment, items, common, True)
        return self.get_top()

    def get_top(self) -> AbstractState:
        return PredicateAbstractState({v: LinExpr.symbol(v) for v in self.variables})

    def get_bottom(self) -> AbstractState:
        return PredicateAbstractState(
            {v: LinExpr.symbol(v) for v in self.variables},
            [Constraint.equal(LinExpr.value(1))],
        )


# ---------------------------------------------------------------------------
# Transfer relation
# ---------------------------------------------------------------------------


class PredicateTransferRelation(TransferRelation):
    """Strongest postcondition plus path-feasibility pruning.

    ``abstraction_locations`` are the CFA nodes at which the precise path
    formula is replaced by its predicate abstraction (normally the loop heads).
    ``forced_invariants`` maps such a node to predicates that are known to hold
    there (used by k-induction); if a node has no entry, the predicates of
    ``basis`` that are entailed by the path formula are computed instead.
    """

    def __init__(self, cfa: CFA, checker: PathFeasibilityChecker,
                 encoder: SymbolicEncoder,
                 basis: Sequence[Predicate] = (),
                 abstraction_locations: Iterable[int] = (),
                 forced_invariants: Optional[dict[int, Sequence[Predicate]]] = None,
                 variables: Optional[Sequence[str]] = None):
        self.cfa = cfa
        self.checker = checker
        self.encoder = encoder
        self.basis = sorted_predicates(basis)
        self.abstraction_locations = set(abstraction_locations)
        self.forced_invariants = forced_invariants or {}
        self.abstraction_locations.update(self.forced_invariants)
        variable_names = list(variables) if variables is not None else list(cfa.variables)
        for predicate in self.basis:
            for name in predicate.variables():
                if name not in variable_names:
                    variable_names.append(name)
        for predicates in self.forced_invariants.values():
            for predicate in predicates:
                for name in predicate.variables():
                    if name not in variable_names:
                        variable_names.append(name)
        self.variables = variable_names
        self.abstractions = 0
        self.pruned_paths = 0

    # -- helpers --------------------------------------------------------
    def canonical_environment(self) -> dict[str, LinExpr]:
        return {name: LinExpr.symbol(name) for name in self.variables}

    def initial_state(self) -> PredicateAbstractState:
        """All variables hold an arbitrary (unconstrained) value."""
        environment = {name: LinExpr.symbol(self.encoder.symbols.fresh(name))
                       for name in self.variables}
        return PredicateAbstractState(environment)

    def entails_predicate(self, state: PredicateAbstractState,
                          predicate: Predicate) -> bool:
        side: list = []
        environment = dict(state.environment)
        negated = predicate.encode_negation(self.encoder, environment, side)
        query = list(state.items) + side + negated
        return self.checker.is_infeasible(query)

    def abstract(self, location: int,
                 state: PredicateAbstractState) -> PredicateAbstractState:
        """Replace the path formula by the predicates that hold at ``location``."""
        self.abstractions += 1
        forced = self.forced_invariants.get(location)
        if forced is not None:
            kept = sorted_predicates(forced)
        else:
            kept = tuple(p for p in self.basis if self.entails_predicate(state, p))

        environment = self.canonical_environment()
        items: list = []
        for predicate in kept:
            side: list = []
            encoded = predicate.encode(self.encoder, dict(environment), side)
            items.extend(side)
            items.extend(encoded)
        simplified = simplify_items(items)
        if simplified is None:                # cannot happen for entailed sets
            simplified = []
        return PredicateAbstractState(environment, simplified, kept, abstracted=True)

    # -- transfer -------------------------------------------------------
    def get_abstract_successors(self, state: AbstractState, precision: Precision,
                                edge: CFAEdge) -> list[AbstractState]:
        environment = dict(state.environment)
        items = list(state.items)
        etype = edge.edge_type

        if etype is EdgeType.ASSIGNMENT:
            side: list = []
            try:
                ast = parse_expression(edge.expression)
                value = self.encoder.encode_term(ast, environment, side)
            except (ExpressionSyntaxError, NonLinearError):
                side = []
                value = LinExpr.symbol(self.encoder.symbols.fresh(edge.variable))
            environment[edge.variable] = value
            items.extend(side)

        elif etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            side = []
            try:
                ast = parse_expression(edge.expression)
                condition = self.encoder.encode_condition(
                    ast, environment, etype is EdgeType.ASSUME_TRUE, side)
            except (ExpressionSyntaxError, NonLinearError):
                side, condition = [], []      # unsupported: keep both branches
            items.extend(side)
            items.extend(condition)

        simplified = simplify_items(items)
        if simplified is None:
            self.pruned_paths += 1
            return []
        if etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            if self.checker.is_infeasible(simplified):
                self.pruned_paths += 1
                return []

        successor = PredicateAbstractState(environment, simplified)
        if edge.target in self.abstraction_locations:
            successor = self.abstract(edge.target, successor)
        return [successor]


class PredicateStopOperator(StopOperator):
    """Covered if an already reached state logically implies the new one."""

    def __init__(self, domain: PredicateDomain):
        self.domain = domain

    def stop(self, state: AbstractState, reached: set, precision: Precision) -> bool:
        for other in reached:
            if self.domain.is_less_or_equal(state, other):
                return True
        return False


class PredicateCPA(ConfigurableProgramAnalysis):
    """CPA for the symbolic predicate analysis."""

    def __init__(self, cfa: CFA, basis: Sequence[Predicate] = (),
                 abstraction_locations: Iterable[int] = (),
                 checker: Optional[PathFeasibilityChecker] = None,
                 encoder: Optional[SymbolicEncoder] = None,
                 forced_invariants: Optional[dict[int, Sequence[Predicate]]] = None):
        self.cfa = cfa
        self.checker = checker or PathFeasibilityChecker()
        self.encoder = encoder or SymbolicEncoder(SymbolFactory())
        self._transfer = PredicateTransferRelation(
            cfa, self.checker, self.encoder, basis, abstraction_locations,
            forced_invariants,
        )
        self._domain = PredicateDomain(self._transfer.variables)
        self._merge = SepMergeOperator()
        self._stop = PredicateStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return self._transfer.initial_state()

    def get_initial_precision(self) -> Precision:
        return SingletonPrecision()


# ---------------------------------------------------------------------------
# Predicate basis and refinement
# ---------------------------------------------------------------------------


def _is_useful(predicate: Predicate, variables: Sequence[str]) -> bool:
    """Drop predicates that are trivially true or trivially false."""
    encoder = SymbolicEncoder(SymbolFactory())
    environment = {name: LinExpr.symbol(name) for name in variables}
    for name in predicate.variables():
        environment.setdefault(name, LinExpr.symbol(name))
    side: list = []
    try:
        items = predicate.encode(encoder, environment, side)
    except (ExpressionSyntaxError, NonLinearError):
        return False
    simplified = simplify_items(list(side) + list(items))
    return bool(simplified)


def build_predicate_basis(cfa: CFA) -> tuple:
    """Derive candidate predicates from the program text.

    * every atom of an assume edge, in both polarities,
    * the equality induced by every (linear, deterministic) assignment.
    """
    predicates: set[Predicate] = set()
    for edge in cfa.edges:
        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                continue
            for atom in collect_atoms(ast):
                if contains_nondet(atom) or not atom.variables():
                    continue
                predicates.add(Predicate(atom, True))
                predicates.add(Predicate(atom, False))
        elif edge.edge_type is EdgeType.ASSIGNMENT and edge.variable:
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                continue
            if contains_nondet(ast):
                continue
            predicates.add(Predicate(Binary("==", Var(edge.variable), ast), True))
    return sorted_predicates(p for p in predicates if _is_useful(p, cfa.variables))


def refine_from_path(cfa: CFA, edges: Sequence[CFAEdge],
                     basis: Sequence[Predicate],
                     loop_heads: Iterable[int]) -> tuple:
    """Counterexample-guided refinement.

    The atoms of the assume edges on a spurious path are propagated backwards
    through the assignments (weakest precondition) and, whenever a loop head is
    crossed, recorded as new candidate predicates for the abstraction.
    """
    loop_heads = set(loop_heads)
    known = set(basis)
    pending: list[Expr] = []
    discovered: set[Predicate] = set()

    for edge in reversed(list(edges)):
        if edge.edge_type is EdgeType.ASSIGNMENT and edge.variable:
            try:
                value = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                pending = []
            else:
                if contains_nondet(value):
                    pending = [a for a in pending
                               if edge.variable not in a.variables()]
                else:
                    pending = [substitute_ast(a, {edge.variable: value})
                               for a in pending]
        elif edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                ast = None
            if ast is not None:
                for atom in collect_atoms(ast):
                    if not contains_nondet(atom) and atom.variables():
                        pending.append(atom)
        pending = pending[-32:]

        if edge.source in loop_heads:
            for atom in pending:
                for positive in (True, False):
                    candidate = Predicate(atom, positive)
                    if candidate not in known and _is_useful(candidate, cfa.variables):
                        discovered.add(candidate)
    return sorted_predicates(discovered)


# ---------------------------------------------------------------------------
# Precise path replay (counterexample validation and witnesses)
# ---------------------------------------------------------------------------


class PathStep:
    """One step of a counterexample: the edge taken and the resulting state."""

    __slots__ = ("edge", "state")

    def __init__(self, edge: Optional[CFAEdge], state: PredicateAbstractState):
        self.edge = edge
        self.state = state


def replay_path(cfa: CFA, edges: Sequence[CFAEdge],
                checker: Optional[PathFeasibilityChecker] = None):
    """Re-execute a path symbolically without abstraction.

    Returns ``(feasible, steps)``; ``feasible`` is ``True`` only if the precise
    path formula of the whole path is satisfiable, i.e. the counterexample is
    genuine and not an artefact of the abstraction.
    """
    checker = checker or PathFeasibilityChecker()
    encoder = SymbolicEncoder(SymbolFactory())
    transfer = PredicateTransferRelation(cfa, checker, encoder)
    state = transfer.initial_state()
    steps = [PathStep(None, state)]
    for edge in edges:
        successors = transfer.get_abstract_successors(state, None, edge)
        if not successors:
            return False, steps
        state = successors[0]
        steps.append(PathStep(edge, state))
    return checker.is_feasible(state.items), steps


def describe_witness(steps: Sequence[PathStep]) -> list[str]:
    """Render a counterexample with the variable values of every step."""
    if not steps:
        return []
    final = steps[-1].state
    model = find_model(final.items, _witness_symbols(steps))
    lines: list[str] = []
    for index, step in enumerate(steps):
        assignments = []
        for variable in sorted(step.state.environment):
            value = step.state.environment[variable]
            concrete = _evaluate(value, model) if model is not None else None
            assignments.append(f"{variable}={concrete if concrete is not None else value}")
        if step.edge is None:
            operation = "initial state"
            location = f"N{0}"
        else:
            operation = _describe_operation(step.edge)
            location = f"N{step.edge.target}"
        lines.append(f"{index}: {location} {operation} :: " + ", ".join(assignments))
    return lines


def _witness_symbols(steps: Sequence[PathStep]) -> list[str]:
    symbols: list[str] = []
    for step in steps:
        for variable in sorted(step.state.environment):
            for symbol in sorted(step.state.environment[variable].symbols()):
                if symbol not in symbols:
                    symbols.append(symbol)
    for item in steps[-1].state.items:
        for symbol in sorted(item.symbols()):
            if symbol not in symbols:
                symbols.append(symbol)
    return symbols


def _evaluate(expr: LinExpr, model: dict[str, int]) -> Optional[int]:
    total = expr.constant
    for symbol, coefficient in expr.terms.items():
        if symbol not in model:
            return None
        total += coefficient * model[symbol]
    return total


def _describe_operation(edge: CFAEdge) -> str:
    if edge.edge_type is EdgeType.ASSIGNMENT:
        return f"{edge.variable} = {edge.expression}"
    if edge.edge_type is EdgeType.ASSUME_TRUE:
        return f"[{edge.expression}]"
    if edge.edge_type is EdgeType.ASSUME_FALSE:
        return f"[!({edge.expression})]"
    if edge.edge_type is EdgeType.ASSERT:
        return "assertion violated"
    return edge.edge_type.value


def edges_of_path(path: Sequence[tuple]) -> list[CFAEdge]:
    """Extract the CFA edges from an :class:`AlgorithmResult` error path."""
    return [edge for _, edge in path if edge is not None]


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def run_predicate_analysis(cfa: CFA, timelimit: float = 900.0) -> VerificationResult:
    """Verify ``cfa`` with LocationCPA x PredicateCPA (+ CEGAR refinement)."""
    start = time.time()
    loop_heads = find_loop_heads(cfa)
    basis = build_predicate_basis(cfa)
    statistics = {
        "analysis": "predicateAnalysis",
        "loop heads": len(loop_heads),
        "abstraction predicates": len(basis),
    }

    for refinement in range(MAX_REFINEMENTS + 1):
        remaining = timelimit - (time.time() - start)
        if remaining <= 0:
            statistics["reason"] = "timeout"
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

        checker = PathFeasibilityChecker()
        cpa = CompositeCPA([
            LocationCPA(cfa),
            PredicateCPA(cfa, basis, loop_heads, checker),
        ])
        algorithm = CPAAlgorithm(cpa, cfa, timelimit=remaining,
                                 max_states=MAX_PREDICATE_STATES)
        outcome = algorithm.run()

        statistics.update({
            "refinements": refinement,
            "abstraction predicates": len(basis),
            "reached states": len(outcome.reached) if outcome.reached else 0,
            "iterations": outcome.iterations,
        })
        statistics.update(checker.statistics())

        if outcome.target_state is None:
            if outcome.exhausted:
                return VerificationResult(verdict=Verdict.TRUE, statistics=statistics)
            statistics["reason"] = ("timeout" if outcome.timed_out
                                    else "state limit reached")
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

        edges = edges_of_path(outcome.error_path)
        feasible, steps = replay_path(cfa, edges)
        if feasible:
            witness = describe_witness(steps)
            statistics["counterexample length"] = len(witness)
            statistics["counterexample"] = " | ".join(witness)
            return VerificationResult(
                verdict=Verdict.FALSE,
                property_violated="assertion",
                error_path=witness,
                statistics=statistics,
            )

        statistics["spurious counterexamples"] = refinement + 1
        discovered = refine_from_path(cfa, edges, basis, loop_heads)
        if not discovered:
            statistics["reason"] = "refinement found no new predicates"
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)
        basis = sorted_predicates(list(basis) + list(discovered))

    statistics["reason"] = "refinement limit reached"
    return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

toolUseResult.stdout:
"""Predicate analysis: symbolic path formulas with feasibility checking.

Instead of concrete values (see :mod:`cpachecker.analyses.value_analysis`) this
analysis tracks *symbolic* knowledge:

* every program variable is mapped to an affine term over symbols
  (``x -> nondet@2 - 1``), which is the strongest postcondition of the
  assignments seen along the path, and
* the path constraints collected from the assume edges.

Whenever an assume edge is processed the resulting constraint set is handed to
the :class:`PathFeasibilityChecker`; infeasible paths are pruned immediately,
which is what makes the analysis able to verify programs over
nondeterministic inputs.

To obtain a *terminating* analysis for programs with loops, the precise path
formula is abstracted at loop heads (adjustable-block encoding): only those
predicates of a finite basis that are entailed by the path formula are kept.
The basis is derived from the program itself (the atoms of all assume edges
and the equalities induced by assignments) and can be extended by a
counterexample-guided refinement step.
"""

from __future__ import annotations

import time
from typing import Iterable, Optional, Sequence

from cpachecker.analyses.linear_arithmetic import (
    Clause,
    Constraint,
    LinExpr,
    NonLinearError,
    SolverLimits,
    entails,
    find_model,
    is_satisfiable,
    negate_items,
)
from cpachecker.analyses.loops import find_loop_heads
from cpachecker.analyses.symbolic_expressions import (
    Binary,
    Expr,
    ExpressionSyntaxError,
    Num,
    SymbolFactory,
    SymbolicEncoder,
    Unary,
    Var,
    Call,
    collect_atoms,
    contains_nondet,
    parse_expression,
)
from cpachecker.analyses.value_analysis import (
    CPAAlgorithm,
    CompositeCPA,
    LocationCPA,
    SepMergeOperator,
    SingletonPrecision,
    describe_path,
)
from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.result import Verdict, VerificationResult

MAX_REFINEMENTS = 3
MAX_PREDICATE_STATES = 60000


# ---------------------------------------------------------------------------
# Predicates
# ---------------------------------------------------------------------------


class Predicate:
    """An atomic condition (or its negation) used as abstraction predicate."""

    __slots__ = ("ast", "positive", "key")

    def __init__(self, ast: Expr, positive: bool = True):
        self.ast = ast
        self.positive = positive
        self.key = (repr(ast), positive)

    def encode(self, encoder: SymbolicEncoder, environment: dict[str, LinExpr],
               side_constraints: list) -> list:
        return encoder.encode_condition(self.ast, environment, self.positive,
                                        side_constraints)

    def encode_negation(self, encoder: SymbolicEncoder,
                        environment: dict[str, LinExpr],
                        side_constraints: list) -> list:
        return encoder.encode_condition(self.ast, environment, not self.positive,
                                        side_constraints)

    def variables(self) -> set[str]:
        return self.ast.variables()

    def __eq__(self, other) -> bool:
        return isinstance(other, Predicate) and other.key == self.key

    def __hash__(self) -> int:
        return hash(self.key)

    def __repr__(self) -> str:
        return repr(self.ast) if self.positive else f"!{self.ast!r}"


def sorted_predicates(predicates: Iterable[Predicate]) -> tuple:
    """Deterministic order (frozenset iteration order is not stable)."""
    return tuple(sorted(set(predicates), key=lambda p: p.key))


def substitute_ast(node: Expr, mapping: dict[str, Expr]) -> Expr:
    """Replace variables by expressions inside an AST (used for refinement)."""
    if isinstance(node, Var):
        return mapping.get(node.name, node)
    if isinstance(node, Num):
        return node
    if isinstance(node, Unary):
        return Unary(node.operator, substitute_ast(node.operand, mapping))
    if isinstance(node, Binary):
        return Binary(node.operator, substitute_ast(node.left, mapping),
                      substitute_ast(node.right, mapping))
    if isinstance(node, Call):
        return Call(node.name, [substitute_ast(a, mapping) for a in node.arguments])
    return node


# ---------------------------------------------------------------------------
# Constraint solving front-end
# ---------------------------------------------------------------------------


class PathFeasibilityChecker:
    """Maintains a set of linear constraints and answers SAT/UNSAT queries.

    The checker is a thin, memoising front-end for
    :mod:`cpachecker.analyses.linear_arithmetic`: equality reasoning (Gaussian
    elimination), interval propagation, Fourier-Motzkin elimination and modular
    (congruence) reasoning.
    """

    SAT = "SAT"
    UNSAT = "UNSAT"

    def __init__(self, limits: Optional[SolverLimits] = None):
        self.limits = limits or SolverLimits()
        self.constraints: list = []
        self.queries = 0
        self.cache_hits = 0
        self.unsat_results = 0
        self._cache: dict[tuple, str] = {}

    # -- the maintained constraint set ----------------------------------
    def add(self, item) -> None:
        self.constraints.append(item)

    def add_all(self, items: Iterable) -> None:
        self.constraints.extend(items)

    def reset(self, items: Iterable = ()) -> None:
        self.constraints = list(items)

    def check(self) -> str:
        """SAT/UNSAT for the currently maintained constraint set."""
        return self.check_items(self.constraints)

    # -- stateless queries ----------------------------------------------
    def check_items(self, items: Sequence) -> str:
        key = tuple(items)
        cached = self._cache.get(key)
        if cached is not None:
            self.cache_hits += 1
            return cached
        self.queries += 1
        verdict = self.SAT if is_satisfiable(key, self.limits) else self.UNSAT
        if verdict == self.UNSAT:
            self.unsat_results += 1
        if len(self._cache) < 100000:
            self._cache[key] = verdict
        return verdict

    def is_feasible(self, items: Sequence) -> bool:
        return self.check_items(items) == self.SAT

    def is_infeasible(self, items: Sequence) -> bool:
        return self.check_items(items) == self.UNSAT

    def implies(self, items: Sequence, consequence: Sequence) -> bool:
        """Check whether ``items`` logically implies ``consequence``."""
        negated = negate_items(list(consequence))
        if negated.is_false:
            return True
        return self.is_infeasible(list(items) + [negated])

    def statistics(self) -> dict:
        return {
            "solver queries": self.queries,
            "solver cache hits": self.cache_hits,
            "solver unsat results": self.unsat_results,
        }


def simplify_items(items: Iterable) -> Optional[list]:
    """Drop trivially true items; return ``None`` if an item is false."""
    result: list = []
    for item in items:
        if isinstance(item, Constraint):
            if item.expr.is_constant:
                constant = item.expr.constant
                if item.kind == Constraint.EQ and constant != 0:
                    return None
                if item.kind == Constraint.GEQ and constant < 0:
                    return None
                if (item.kind == Constraint.MOD and item.modulus > 1
                        and constant % item.modulus != 0):
                    return None
                continue                      # trivially true
            result.append(item)
        else:
            if item.is_false:
                return None
            if item.is_unit:
                nested = simplify_items(item.alternatives[0])
                if nested is None:
                    return None
                result.extend(nested)
                continue
            result.append(item)
    return list(dict.fromkeys(result))


# ---------------------------------------------------------------------------
# Abstract state
# ---------------------------------------------------------------------------


class PredicateAbstractState(AbstractState):
    """Symbolic environment plus a set of path constraints."""

    __slots__ = ("environment", "items", "predicates", "abstracted", "_key", "_hash")

    def __init__(self, environment: dict[str, LinExpr], items: Iterable = (),
                 predicates: Iterable[Predicate] = (), abstracted: bool = False):
        self.environment = dict(environment)
        self.items = tuple(items)
        self.predicates = frozenset(predicates)
        self.abstracted = abstracted
        if abstracted:
            # Abstract states are canonical: the predicate set identifies them.
            self._key = ("abstract", tuple(sorted(p.key for p in self.predicates)))
        else:
            self._key = ("path",
                         tuple(sorted((v, repr(e)) for v, e in self.environment.items())),
                         self.items)
        self._hash = hash(self._key)

    # -- queries --------------------------------------------------------
    def value_of(self, variable: str) -> Optional[LinExpr]:
        return self.environment.get(variable)

    def formula(self) -> list:
        return list(self.items)

    def is_less_or_equal(self, other: "PredicateAbstractState") -> bool:
        if self._key == other._key:
            return True
        if self.abstracted and other.abstracted:
            # A state with more predicates is stronger, hence covered.
            return other.predicates <= self.predicates
        return False

    def __eq__(self, other) -> bool:
        return isinstance(other, PredicateAbstractState) and other._key == self._key

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        if self.abstracted:
            predicates = ", ".join(repr(p) for p in sorted(self.predicates,
                                                           key=lambda p: p.key))
            return f"<abs {predicates or 'true'}>"
        assignments = ", ".join(f"{v}={e}" for v, e in sorted(self.environment.items()))
        constraints = ", ".join(repr(i) for i in self.items)
        return f"<{assignments} | {constraints}>"


class PredicateDomain(AbstractDomain):
    """Lattice of predicate states (implication ordering, approximated)."""

    def __init__(self, variables: Sequence[str]):
        self.variables = list(variables)

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        return state1.is_less_or_equal(state2)

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        if state1 == state2:
            return state1
        if state1.abstracted and state2.abstracted:
            common = state1.predicates & state2.predicates
            items = [i for i in state1.items if i in set(state2.items)]
            return PredicateAbstractState(state1.environment, items, common, True)
        return self.get_top()

    def get_top(self) -> AbstractState:
        return PredicateAbstractState({v: LinExpr.symbol(v) for v in self.variables})

    def get_bottom(self) -> AbstractState:
        return PredicateAbstractState(
            {v: LinExpr.symbol(v) for v in self.variables},
            [Constraint.equal(LinExpr.value(1))],
        )


# ---------------------------------------------------------------------------
# Transfer relation
# ---------------------------------------------------------------------------


class PredicateTransferRelation(TransferRelation):
    """Strongest postcondition plus path-feasibility pruning.

    ``abstraction_locations`` are the CFA nodes at which the precise path
    formula is replaced by its predicate abstraction (normally the loop heads).
    ``forced_invariants`` maps such a node to predicates that are known to hold
    there (used by k-induction); if a node has no entry, the predicates of
    ``basis`` that are entailed by the path formula are computed instead.
    """

    def __init__(self, cfa: CFA, checker: PathFeasibilityChecker,
                 encoder: SymbolicEncoder,
                 basis: Sequence[Predicate] = (),
                 abstraction_locations: Iterable[int] = (),
                 forced_invariants: Optional[dict[int, Sequence[Predicate]]] = None,
                 variables: Optional[Sequence[str]] = None):
        self.cfa = cfa
        self.checker = checker
        self.encoder = encoder
        self.basis = sorted_predicates(basis)
        self.abstraction_locations = set(abstraction_locations)
        self.forced_invariants = forced_invariants or {}
        self.abstraction_locations.update(self.forced_invariants)
        variable_names = list(variables) if variables is not None else list(cfa.variables)
        for predicate in self.basis:
            for name in predicate.variables():
                if name not in variable_names:
                    variable_names.append(name)
        for predicates in self.forced_invariants.values():
            for predicate in predicates:
                for name in predicate.variables():
                    if name not in variable_names:
                        variable_names.append(name)
        self.variables = variable_names
        self.abstractions = 0
        self.pruned_paths = 0

    # -- helpers --------------------------------------------------------
    def canonical_environment(self) -> dict[str, LinExpr]:
        return {name: LinExpr.symbol(name) for name in self.variables}

    def initial_state(self) -> PredicateAbstractState:
        """All variables hold an arbitrary (unconstrained) value."""
        environment = {name: LinExpr.symbol(self.encoder.symbols.fresh(name))
                       for name in self.variables}
        return PredicateAbstractState(environment)

    def entails_predicate(self, state: PredicateAbstractState,
                          predicate: Predicate) -> bool:
        side: list = []
        environment = dict(state.environment)
        negated = predicate.encode_negation(self.encoder, environment, side)
        query = list(state.items) + side + negated
        return self.checker.is_infeasible(query)

    def abstract(self, location: int,
                 state: PredicateAbstractState) -> PredicateAbstractState:
        """Replace the path formula by the predicates that hold at ``location``."""
        self.abstractions += 1
        forced = self.forced_invariants.get(location)
        if forced is not None:
            kept = sorted_predicates(forced)
        else:
            kept = tuple(p for p in self.basis if self.entails_predicate(state, p))

        environment = self.canonical_environment()
        items: list = []
        for predicate in kept:
            side: list = []
            encoded = predicate.encode(self.encoder, dict(environment), side)
            items.extend(side)
            items.extend(encoded)
        simplified = simplify_items(items)
        if simplified is None:                # cannot happen for entailed sets
            simplified = []
        return PredicateAbstractState(environment, simplified, kept, abstracted=True)

    # -- transfer -------------------------------------------------------
    def get_abstract_successors(self, state: AbstractState, precision: Precision,
                                edge: CFAEdge) -> list[AbstractState]:
        environment = dict(state.environment)
        items = list(state.items)
        etype = edge.edge_type

        if etype is EdgeType.ASSIGNMENT:
            side: list = []
            try:
                ast = parse_expression(edge.expression)
                value = self.encoder.encode_term(ast, environment, side)
            except (ExpressionSyntaxError, NonLinearError):
                side = []
                value = LinExpr.symbol(self.encoder.symbols.fresh(edge.variable))
            environment[edge.variable] = value
            items.extend(side)

        elif etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            side = []
            try:
                ast = parse_expression(edge.expression)
                condition = self.encoder.encode_condition(
                    ast, environment, etype is EdgeType.ASSUME_TRUE, side)
            except (ExpressionSyntaxError, NonLinearError):
                side, condition = [], []      # unsupported: keep both branches
            items.extend(side)
            items.extend(condition)

        simplified = simplify_items(items)
        if simplified is None:
            self.pruned_paths += 1
            return []
        if etype in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            if self.checker.is_infeasible(simplified):
                self.pruned_paths += 1
                return []

        successor = PredicateAbstractState(environment, simplified)
        if edge.target in self.abstraction_locations:
            successor = self.abstract(edge.target, successor)
        return [successor]


class PredicateStopOperator(StopOperator):
    """Covered if an already reached state logically implies the new one."""

    def __init__(self, domain: PredicateDomain):
        self.domain = domain

    def stop(self, state: AbstractState, reached: set, precision: Precision) -> bool:
        for other in reached:
            if self.domain.is_less_or_equal(state, other):
                return True
        return False


class PredicateCPA(ConfigurableProgramAnalysis):
    """CPA for the symbolic predicate analysis."""

    def __init__(self, cfa: CFA, basis: Sequence[Predicate] = (),
                 abstraction_locations: Iterable[int] = (),
                 checker: Optional[PathFeasibilityChecker] = None,
                 encoder: Optional[SymbolicEncoder] = None,
                 forced_invariants: Optional[dict[int, Sequence[Predicate]]] = None):
        self.cfa = cfa
        self.checker = checker or PathFeasibilityChecker()
        self.encoder = encoder or SymbolicEncoder(SymbolFactory())
        self._transfer = PredicateTransferRelation(
            cfa, self.checker, self.encoder, basis, abstraction_locations,
            forced_invariants,
        )
        self._domain = PredicateDomain(self._transfer.variables)
        self._merge = SepMergeOperator()
        self._stop = PredicateStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return self._transfer.initial_state()

    def get_initial_precision(self) -> Precision:
        return SingletonPrecision()


# ---------------------------------------------------------------------------
# Predicate basis and refinement
# ---------------------------------------------------------------------------


def _is_useful(predicate: Predicate, variables: Sequence[str]) -> bool:
    """Drop predicates that are trivially true or trivially false."""
    encoder = SymbolicEncoder(SymbolFactory())
    environment = {name: LinExpr.symbol(name) for name in variables}
    for name in predicate.variables():
        environment.setdefault(name, LinExpr.symbol(name))
    side: list = []
    try:
        items = predicate.encode(encoder, environment, side)
    except (ExpressionSyntaxError, NonLinearError):
        return False
    simplified = simplify_items(list(side) + list(items))
    return bool(simplified)


def build_predicate_basis(cfa: CFA) -> tuple:
    """Derive candidate predicates from the program text.

    * every atom of an assume edge, in both polarities,
    * the equality induced by every (linear, deterministic) assignment.
    """
    predicates: set[Predicate] = set()
    for edge in cfa.edges:
        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                continue
            for atom in collect_atoms(ast):
                if contains_nondet(atom) or not atom.variables():
                    continue
                predicates.add(Predicate(atom, True))
                predicates.add(Predicate(atom, False))
        elif edge.edge_type is EdgeType.ASSIGNMENT and edge.variable:
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                continue
            if contains_nondet(ast):
                continue
            predicates.add(Predicate(Binary("==", Var(edge.variable), ast), True))
    return sorted_predicates(p for p in predicates if _is_useful(p, cfa.variables))


def refine_from_path(cfa: CFA, edges: Sequence[CFAEdge],
                     basis: Sequence[Predicate],
                     loop_heads: Iterable[int]) -> tuple:
    """Counterexample-guided refinement.

    The atoms of the assume edges on a spurious path are propagated backwards
    through the assignments (weakest precondition) and, whenever a loop head is
    crossed, recorded as new candidate predicates for the abstraction.
    """
    loop_heads = set(loop_heads)
    known = set(basis)
    pending: list[Expr] = []
    discovered: set[Predicate] = set()

    for edge in reversed(list(edges)):
        if edge.edge_type is EdgeType.ASSIGNMENT and edge.variable:
            try:
                value = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                pending = []
            else:
                if contains_nondet(value):
                    pending = [a for a in pending
                               if edge.variable not in a.variables()]
                else:
                    pending = [substitute_ast(a, {edge.variable: value})
                               for a in pending]
        elif edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            try:
                ast = parse_expression(edge.expression)
            except ExpressionSyntaxError:
                ast = None
            if ast is not None:
                for atom in collect_atoms(ast):
                    if not contains_nondet(atom) and atom.variables():
                        pending.append(atom)
        pending = pending[-32:]

        if edge.source in loop_heads:
            for atom in pending:
                for positive in (True, False):
                    candidate = Predicate(atom, positive)
                    if candidate not in known and _is_useful(candidate, cfa.variables):
                        discovered.add(candidate)
    return sorted_predicates(discovered)


# ---------------------------------------------------------------------------
# Precise path replay (counterexample validation and witnesses)
# ---------------------------------------------------------------------------


class PathStep:
    """One step of a counterexample: the edge taken and the resulting state."""

    __slots__ = ("edge", "state")

    def __init__(self, edge: Optional[CFAEdge], state: PredicateAbstractState):
        self.edge = edge
        self.state = state


def replay_path(cfa: CFA, edges: Sequence[CFAEdge],
                checker: Optional[PathFeasibilityChecker] = None):
    """Re-execute a path symbolically without abstraction.

    Returns ``(feasible, steps)``; ``feasible`` is ``True`` only if the precise
    path formula of the whole path is satisfiable, i.e. the counterexample is
    genuine and not an artefact of the abstraction.
    """
    checker = checker or PathFeasibilityChecker()
    encoder = SymbolicEncoder(SymbolFactory())
    transfer = PredicateTransferRelation(cfa, checker, encoder)
    state = transfer.initial_state()
    steps = [PathStep(None, state)]
    for edge in edges:
        successors = transfer.get_abstract_successors(state, None, edge)
        if not successors:
            return False, steps
        state = successors[0]
        steps.append(PathStep(edge, state))
    return checker.is_feasible(state.items), steps


def describe_witness(steps: Sequence[PathStep]) -> list[str]:
    """Render a counterexample with the variable values of every step."""
    if not steps:
        return []
    final = steps[-1].state
    model = find_model(final.items, _witness_symbols(steps))
    lines: list[str] = []
    for index, step in enumerate(steps):
        assignments = []
        for variable in sorted(step.state.environment):
            value = step.state.environment[variable]
            concrete = _evaluate(value, model) if model is not None else None
            assignments.append(f"{variable}={concrete if concrete is not None else value}")
        if step.edge is None:
            operation = "initial state"
            location = f"N{0}"
        else:
            operation = _describe_operation(step.edge)
            location = f"N{step.edge.target}"
        lines.append(f"{index}: {location} {operation} :: " + ", ".join(assignments))
    return lines


def _witness_symbols(steps: Sequence[PathStep]) -> list[str]:
    symbols: list[str] = []
    for step in steps:
        for variable in sorted(step.state.environment):
            for symbol in sorted(step.state.environment[variable].symbols()):
                if symbol not in symbols:
                    symbols.append(symbol)
    for item in steps[-1].state.items:
        for symbol in sorted(item.symbols()):
            if symbol not in symbols:
                symbols.append(symbol)
    return symbols


def _evaluate(expr: LinExpr, model: dict[str, int]) -> Optional[int]:
    total = expr.constant
    for symbol, coefficient in expr.terms.items():
        if symbol not in model:
            return None
        total += coefficient * model[symbol]
    return total


def _describe_operation(edge: CFAEdge) -> str:
    if edge.edge_type is EdgeType.ASSIGNMENT:
        return f"{edge.variable} = {edge.expression}"
    if edge.edge_type is EdgeType.ASSUME_TRUE:
        return f"[{edge.expression}]"
    if edge.edge_type is EdgeType.ASSUME_FALSE:
        return f"[!({edge.expression})]"
    if edge.edge_type is EdgeType.ASSERT:
        return "assertion violated"
    return edge.edge_type.value


def edges_of_path(path: Sequence[tuple]) -> list[CFAEdge]:
    """Extract the CFA edges from an :class:`AlgorithmResult` error path."""
    return [edge for _, edge in path if edge is not None]


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def run_predicate_analysis(cfa: CFA, timelimit: float = 900.0) -> VerificationResult:
    """Verify ``cfa`` with LocationCPA x PredicateCPA (+ CEGAR refinement)."""
    start = time.time()
    loop_heads = find_loop_heads(cfa)
    basis = build_predicate_basis(cfa)
    statistics = {
        "analysis": "predicateAnalysis",
        "loop heads": len(loop_heads),
        "abstraction predicates": len(basis),
    }

    for refinement in range(MAX_REFINEMENTS + 1):
        remaining = timelimit - (time.time() - start)
        if remaining <= 0:
            statistics["reason"] = "timeout"
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

        checker = PathFeasibilityChecker()
        cpa = CompositeCPA([
            LocationCPA(cfa),
            PredicateCPA(cfa, basis, loop_heads, checker),
        ])
        algorithm = CPAAlgorithm(cpa, cfa, timelimit=remaining,
                                 max_states=MAX_PREDICATE_STATES)
        outcome = algorithm.run()

        statistics.update({
            "refinements": refinement,
            "abstraction predicates": len(basis),
            "reached states": len(outcome.reached) if outcome.reached else 0,
            "iterations": outcome.iterations,
        })
        statistics.update(checker.statistics())

        if outcome.target_state is None:
            if outcome.exhausted:
                return VerificationResult(verdict=Verdict.TRUE, statistics=statistics)
            statistics["reason"] = ("timeout" if outcome.timed_out
                                    else "state limit reached")
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

        edges = edges_of_path(outcome.error_path)
        feasible, steps = replay_path(cfa, edges)
        if feasible:
            witness = describe_witness(steps)
            statistics["counterexample length"] = len(witness)
            statistics["counterexample"] = " | ".join(witness)
            return VerificationResult(
                verdict=Verdict.FALSE,
                property_violated="assertion",
                error_path=witness,
                statistics=statistics,
            )

        statistics["spurious counterexamples"] = refinement + 1
        discovered = refine_from_path(cfa, edges, basis, loop_heads)
        if not discovered:
            statistics["reason"] = "refinement found no new predicates"
            return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)
        basis = sorted_predicates(list(basis) + list(discovered))

    statistics["reason"] = "refinement limit reached"
    return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

